'use strict';
// Herr Dr. Foliant is a fictional guide; his examples are scaffolds, not model answers.
const librarianLessons={
babel:{hello:'Ah, Besuch! Ich bin Herr Dr. Foliant. Seit einer Ewigkeit sortiere ich hier Bücher. Leider nach einem System, das ich gestern verlegt habe. Wir beginnen mit Schauen und Suchen. Deuten kommt später.',experiment:['Klicke unten auf „Ein Regal durchsuchen“. Klicke einen der gefundenen Bände an und schau: Kannst du seine Zeichen lesen? Kannst du ihn auch verstehen?','Gehe danach durch die fünf Bilder mit „Weiter“. Wähle EIN Detail: zum Beispiel den Schacht, den Katalog oder das offene Buch.','Merke dir dieses Detail. Im nächsten Schritt suchst du es in Borges’ Erzählung.'],source:'Borges',reading:['Öffne im Buch „borges-bibliothek-von-text.pdf“. Lies zuerst den Anfang; für dein gewähltes Motiv auch die passende spätere Stelle.','Suche eine Stelle zu deinem Bilddetail. Schreibe ein paar Wörter oder die Seitenzahl heraus.','Vergleiche: Was zeigt das Bild? Was steht tatsächlich im Text? Die Bilder sind unsere Deutung, keine Bilder von Borges.'],prompt:'Schreibe drei kurze Sätze: 1. Welches Detail siehst du im Bild? 2. Was sagt Borges an einer konkreten Textstelle dazu? 3. Wo begegnet dir heute etwas Ähnliches – und was ist dort anders?',example:'So kannst du anfangen: „Ich wähle den Schacht. Im Bild … Bei Borges finde ich auf Seite … Heute erinnert mich das an … Anders ist …“ Fülle die Lücken mit deiner Beobachtung. Es gibt keine vorgegebene Deutung.',bridge:'Die Bibliothek enthält unzählige Texte. Aber reicht es, dass ein Text da ist? In der nächsten Galerie erprobst du, was beim Lesen überhaupt bei dir ankommt.'},
attention:{hello:'Psst. Ein Satz ist mir hier zwischen zwei Nachrichten abhandengekommen. Lesen wir zweimal und schauen, was bei dir bleibt.',experiment:['Klicke „Versuch beginnen“. Du liest zwei kurze Szenen. Unterbrechungen darfst du ausschalten.','Klicke nach jeder Szene „Gelesen“, schätze die Anstrengung ein und beantworte die Erinnerungsfrage.','Vergleiche die beiden Ergebnisse. Notiere auch, wenn du keinen Unterschied merkst.'],source:'Superpower',reading:['Öffne „Lesen_Superpower_werbefrei (1).pdf“, S. 1–5.','Wähle eine Behauptung über vertieftes Lesen. Welche Begründung liefert der Artikel?','Vergleiche sie mit deinem kleinen Versuch. Was kannst du damit prüfen – und was bleibt offen?'],prompt:'Notiere: Was fiel dir beim Lesen auf? Welches Ergebnis hast du im Versuch erhalten? Welche Behauptung aus dem Artikel kannst du damit noch NICHT beweisen?',example:'„Mit Unterbrechungen bemerkte ich … Mein Ergebnis war … Daraus kann ich noch nicht schliessen, dass alle Menschen …“ Beobachtung und allgemeine Aussage sind zwei verschiedene Dinge.',bridge:'Eine persönliche Erfahrung ist noch keine Gesellschaftsdiagnose. Jetzt prüfen wir mit Freiwald die Behauptung, dass die Gesellschaft das Lesen verlernt.'},
court:{hello:'Die Anklage lautet: „Die Gesellschaft verlernt das Lesen.“ Mein Stempel sagt: Erst die Akten lesen! Du bist heute die Jury.',experiment:['Stelle den Regler auf dein erstes Urteil und klicke „Erstes Urteil festhalten“.','Öffne alle sechs Akten. Finde eine, die für eine Krise spricht, und eine, die das Bild komplizierter macht.','Gib danach dein zweites Urteil ab. Merke dir, welches Argument etwas verändert hat.'],source:'Freiwald',reading:['Öffne „Verlernen wir zu lesen_.pdf“ von Bent Freiwald. Lies S. 5–8 und S. 9–11.','Markiere eine Stelle über tatsächliche Leseschwierigkeiten und eine über einen problematischen Vergleich mit früher.','Prüfe die Akten daran. Lies als Gegenposition den Einstieg von Horowitch in „The_End_of_Reading_Werbefrei.pdf“.'],prompt:'Vervollständige: „Gefährdet ist vielleicht … Freiwald zeigt an der Stelle … Eine ernst zu nehmende Gegenposition lautet … Mein Urteil ist deshalb …“ Sage konkret, welche Art des Lesens du meinst.',example:'Ein mögliches Gerüst: „Ich unterscheide kurze Alltagslektüre und lange schwierige Texte. Für … spricht die Stelle auf Seite … Dagegen könnte man einwenden …“ Die Textbelege und dein Urteil musst du selbst wählen.',bridge:'Freiwald erinnert daran, dass Klagen über das Lesen eine lange Geschichte haben. Kommen Sie – entschuldige: komm mit in mein Museum der angeblich guten alten Zeit.'},
nostalgia:{hello:'Früher war alles besser. Behauptet zumindest dieses staubige Etikett. Ich habe vorsichtshalber das Datum abgedeckt.',experiment:['Schalte die Zeitmaschine ein. Ordne die vier Klagen einem Jahr zu.','Lies nach jeder Wahl die Auflösung. Achte darauf, welches Medium jeweils schuld sein soll.','Hebe danach die beiden Erinnerungsauswahlen auf. Was wurde vorher weggelassen?'],source:'Freiwald',reading:['Lies bei Freiwald S. 2–3 zu historischen Leseängsten.','Wähle eine frühere Warnung. Worin ähnelt sie einer Warnung, die du heute kennst?','Eine wiederholte Warnung kann trotzdem zutreffen. Suche, welchen aktuellen Beleg man zur Prüfung bräuchte.'],prompt:'Wähle eine Warnung aus dem Raum. Warum klang sie glaubwürdig? Welche konkrete Information bräuchtest du, um zu prüfen, ob Lesen tatsächlich schlechter geworden ist?',example:'„Die Warnung über … überzeugte mich zunächst, weil … Zum Prüfen bräuchte ich einen Vergleich von … in den Jahren … bei derselben Gruppe.“',bridge:'Nun verlassen wir die Zeitmaschine. Wer überhaupt Zeit und Hilfe zum Lesen hat, sieht man im Bücherregal leider nicht.'},
access:{hello:'Vier Personen, dasselbe Buch. Also dieselbe Chance? Wenn das nur so einfach wäre. Ich habe ein paar Hilfen aus meiner Manteltasche geholt.',experiment:['Lies die Ausgangslage der vier erfundenen Personen.','Verteile die vier Unterstützungsangebote. Schau, wie sich ihre Möglichkeiten verändern.','Klicke „Die Türen öffnen“. Wähle danach unten eine Barriere, die unser einfaches Modell noch nicht berücksichtigt.'],source:'Amlinger',reading:['Öffne Amlingers „CarolinAmlinger_Lesen.docx“ oder das zugehörige Audio. Prüfe unklare Transkriptstellen am Audio.','Lies oder höre den Anfang und Schluss: Welche Rolle spielen Zeit, Lebensbedingungen und Bücherbesitz?','Finde einen Gedanken, der eine Entscheidung in deinem Versuch erklärt oder infrage stellt.'],prompt:'Wem hast du welche Hilfe gegeben – und warum? Welche Bedingung blieb trotzdem schwierig? Verknüpfe eine Entscheidung mit einem Gedanken aus Amlinger.',example:'„Ich gab … die Hilfe …, weil … Trotzdem blieb … Amlinger hilft mir, das zu verstehen, indem sie …“ Die Personen sind erfunden; dein Ergebnis ist keine Statistik.',bridge:'Und wenn die Zeit fehlt: Kann jemand anderes für uns lesen? Im nächsten Raum bietet sich ein sehr selbstsicherer Stellvertreter an.'},
delegate:{hello:'Meine Kurzfassung ist ausgezeichnet. Sagt meine Kurzfassung. Bitte trau ihr nicht gleich – auch ich verlege gelegentlich das Entscheidende.',experiment:['Lies zuerst die Kurzfassung und bilde ein vorläufiges Urteil.','Öffne dann den Originaltext im Versuch. Suche, was in der Kurzfassung fehlt oder falsch dargestellt ist.','Vergleiche deine Urteile. Welche Information hätte der Stellvertreter unbedingt mitliefern müssen?'],source:'Engemann',reading:['Öffne Engemanns „Die Zukunft des Lesens“. Suche die Kapitel „Krise des Lesens“ und „Ein Neues Latein“.','Achte darauf, wer selbst liest und wer sich auf andere verlassen muss.','Prüfe damit deinen Versuch: Was wird bequem, was wird abhängig?'],prompt:'Was hast du nach der Kurzfassung angenommen? Was änderte der Originaltext? Formuliere eine konkrete Prüfregel für Zusammenfassungen und verbinde sie mit Engemann.',example:'„Zuerst dachte ich … Im Original stand jedoch … Bevor ich eine Kurzfassung übernehme, werde ich …“ Eine Prüfregel kann etwa festlegen, welche Stelle du selbst nachliest.',bridge:'Nicht nur Kurzfassungen wählen für dich aus. Gleich begegnen wir einem Regal, das sich an deine Vorlieben erinnert.'},
bubble:{hello:'Ein wunderbares Regal: Es bringt dir immer mehr von dem, was du schon magst. Bis du vergisst, was daneben stehen könnte.',experiment:['Wähle im Empfehlungsregal mehrere Texte, die dich ansprechen.','Beobachte, wie sich die angebotenen Titel verändern.','Nutze die Möglichkeit, die Auswahl zu öffnen. Welche neue Sicht taucht auf?'],source:'Lauer',reading:['Öffne Lauers „Lesen im digitalen Zeitalter“. Schau in die Kapitel 3, 5 oder 8.','Suche eine Passage zu digitalen Lese- oder Schreibgemeinschaften.','Vergleiche Chancen der Gemeinschaft mit der Auswahlverengung im Versuch.'],prompt:'Welche Auswahl hast du selbst getroffen? Was hat das Regal daraufhin verstärkt? Nenne einen Gewinn und einen möglichen Verlust und beziehe einen Gedanken von Lauer ein.',example:'„Ich wählte oft … Danach sah ich mehr … Hilfreich war … Gefehlt hat … Bei Lauer finde ich dazu …“ Unser Regal ist eine vereinfachte Simulation.',bridge:'Nun wird es ausgesprochen dekorativ. Im nächsten Raum zählen wir Bücher – und fragen, was ein Bücherbild überhaupt zeigt.'},
bookish:{hello:'Diese Bücher passen hervorragend zu meiner Weste. Aber habe ich sie gelesen? Hm. Blättern wir hinter die Fassade.',experiment:['Gestalte dein Bücherbild mit den angebotenen Ansichten und Reglern.','Vergleiche Bücherbesitz und gelesene Bücher. Verändert sich der Eindruck?','Sammle unten die Leseformen deines Tages. Welche fehlen auf einem Foto vom Regal?'],source:'Pressman',reading:['Öffne „Bookishness_Jessica_Pressman.pdf“ oder DOCX. Es ist eine erläuternde Darstellung des Begriffs.','Lies Begriff und Beispiele: Wie wird das Buch als sichtbares Objekt benutzt?','Wende den Begriff auf dein gestaltetes Bild an.'],prompt:'Was erzählt dein Bücherbild über dich? Was lässt es über dein tatsächliches Lesen offen? Erkläre „Bookishness“ an einem konkreten Detail des Bildes.',example:'„Mein Bild zeigt … Man kann daraus aber nicht erkennen, ob … Mit Bookishness lässt sich das Detail … beschreiben, weil …“',bridge:'Ein Buch ist ein Träger. Aber Gedanken reisen auch durch Stimmen, Feeds und Maschinen. Probieren wir das Schreibzeug aus.'},
media:{hello:'Dieser Satz hat vier Mäntel. Im Feed sitzt einer zu eng. In der Stimme raschelt ein anderer. Zieh dem Gedanken verschiedene Werkzeuge an.',experiment:['Gib denselben Gedanken nacheinander in Buchseite, Feed, Zeichenapparat und Stimme.','Lege mindestens zwei Versionen ins Protokoll. Bei der Stimme kannst du freiwillig vorlesen lassen.','Vergleiche ein Detail: Welche Nuance blieb, welche ging verloren?'],source:'Nantke',reading:['Öffne „Schreiben und Lesen“ von Julia Nantke: PDF „bda8476b-8a9e-4f83-851f-e7afa6a08639.pdf“.','Lies den Einstieg mit Nietzsche und seinen Schreibwerkzeugen.','Suche einen Gedanken darüber, wie Werkzeuge am Schreiben und Denken mitwirken.'],prompt:'Vergleiche zwei deiner Versionen an konkreten Wörtern. Was wurde leichter, was ging verloren? Wer entscheidet über die Regeln des Werkzeugs? Verbinde das mit Nantke.',example:'„In der Buchversion steht … Im Feed fehlt … Dadurch wirkt … Die Beschränkung wurde von … festgelegt.“',bridge:'Jetzt genügt ein einziger kleiner Text. Er zeigt, wie viel wir beim Lesen selbst dazuerfinden.'},
resonance:{hello:'Ich kenne die Frau auf der Treppe nicht. Trotzdem habe ich sofort eine Geschichte über sie im Kopf. Du auch? Sehen wir genau hin.',experiment:['Lies die kurze Szene mit der Frau und dem Buch. Wähle deine erste Vermutung.','Schreibe zwei Sätze aus Sicht des Mannes.','Erfinde einen Satz der Frau, der deiner ersten Vermutung widerspricht.'],source:'Rosa',reading:['Öffne Hartmut Rosas Einzelbeitrag „Vom Wunder narrativer Resonanz“ direkt als PDF. Weitere Stimmen stehen als eigene Bände in den Regalen und im Stimmenverzeichnis.','Lies einen zugänglichen Abschnitt und finde einen Grund fürs Lesen, der dich anspricht.','Überlege eine Situation, in der dieser Grund nicht für alle gilt.'],prompt:'Welche Annahme hast du zuerst über die Frau gemacht? Was hat den Blickwechsel ausgelöst? Formuliere einen persönlichen Grund fürs Lesen und nenne eine Grenze dieses Grundes.',example:'„Ich nahm an … Der Text sagte eigentlich nur … Beim Perspektivwechsel bemerkte ich … Für mich ist Lesen …, aber nicht in jeder Situation …“',bridge:'Wir haben viel erlebt und noch mehr offene Fragen gesammelt. Die letzte Galerie gehört deinen eigenen Entscheidungen.'},
future:{hello:'Aha, die letzte lesende Person! Keine Sorge, du bist nicht allein. Entwirf eine Bibliothek, in der auch andere Platz und Zeit zum Lesen finden.',experiment:['Verteile genau 100 Minuten auf die vier Leseformen.','Übernimm den Entwurf ins Logbuch und ergänze fünf konkrete Regeln für den nächsten Monat.','Prüfe: Welche Möglichkeit gewinnt Zeit – und welche muss dafür zurückstehen?'],source:'Freiwald',reading:['Kehre zu Freiwald S. 9–11 und einer selbst gewählten Borges-Stelle zurück.','Suche bei Freiwald einen Gedanken zu Förderung oder delegiertem Lesen.','Verbinde eine deiner Regeln mit Freiwald und eine andere mit Borges.'],prompt:'Schreibe deine fünf Regeln mit je einem nächsten Schritt. Beziehe zwei davon auf Borges und Freiwald. Welche Regel könnte schwierig sein? Was prüfst du nach einem Monat?',example:'„Nächste Woche werde ich …, damit … Das passt zu Freiwalds Gedanken … Meine zweite Regel reagiert auf Borges’ … Nach einem Monat prüfe ich …“',bridge:'Du hast die letzte Galerie erreicht. Kein Abschlussstempel von mir! Exportiere dein Logbuch und wähle eine Regel, die du wirklich ausprobieren möchtest.'}
};
function librarianStageMarkup(){return `<aside class="librarian-companion" aria-label="Herr Dr. Foliant, dein Bibliothekar"><button class="librarian-person" id="librarian-toggle" aria-expanded="true" aria-controls="librarian-speech"><span>Herr Dr. Foliant<br><small>An seinem Pult · Frag mich</small></span></button><div class="librarian-speech" id="librarian-speech"><div class="librarian-name">Herr Dr. Foliant · dein Bibliothekar<button id="librarian-fold" aria-label="Bibliothekar einklappen">−</button></div><div id="librarian-message"></div><div id="librarian-actions"></div></div></aside>`;}
function librarianBookIntro(id,kind,sourceId){const l=librarianLessons[id],s=sources.find(x=>x[0]===sourceId),voice=foliantDrama[id]?.voices.find(v=>v[0]===sourceId),reading=voice?[`Öffne den Originaltext: ${s[1]}.`,voice[2],'Notiere eine konkrete Stelle. Prüfe, ob sie deine Antwort auf die Raumfrage verändert.']:sourceId===l.source?l.reading:s?.[6]?[`Öffne den Originaltext: ${s[1]}.`,s[4],'Notiere eine konkrete Seite und deinen eigenen Gedanken. Vergleiche mit einer anderen Stimme im Stimmenverzeichnis.']:sourceId&&sourceId!==l.source?[`Öffne im Buch: ${s[1]}.`,s[4],"Wähle eine Aussage, die zu deiner Beobachtung im Raum passt oder ihr widerspricht. Notiere Seite oder Abschnitt." ]:l.reading,phase=kind==='experiment'?0:kind==='resource'?1:2;return `<section class="librarian-inbook" aria-label="Leseauftrag von Herrn Dr. Foliant"><img src="assets/librarian.png" alt="Herr Dr. Foliant"><div><span class="eyebrow">Herr Dr. Foliant erklärt</span><h3>${id==='babel'?{resource:'Zuerst Borges vollständig lesen.',question:'Dann die Erzählung studieren.',experiment:'Jetzt die Inszenierung am Text prüfen.'}[kind]:['Zuerst etwas ausprobieren.','Jetzt am Text prüfen.','Jetzt deinen Gedanken festhalten.'][phase]}</h3><p>${id==='babel'?(kind==='resource'?'„Zuerst deine Begegnung mit der Erzählung. Meine Deutung kommt später.“':kind==='question'?'„Lies genau und belege deine Beobachtungen. Die offene Frage nehmen wir mit auf die Reise.“':'„Jetzt darfst du meine Bilder mit Borges vergleichen. Verwechsle die Inszenierung nicht mit dem Original.“'):phase===0?'„Keine grosse Theorie. Mach diese Schritte und beobachte dich dabei.“':phase===1?'„Der Versuch wirft eine Frage auf. Der Text hilft dir, genauer hinzusehen.“':'„Du brauchst keine fertige Deutung. Ein paar genaue Sätze reichen. Wenn dir noch ein Bild oder Text fehlt, gehen wir einen Schritt zurück.“'}</p></div>${phase===1?`<div class="librarian-original-link"><a class="btn" href="${s[6]}" target="_blank" rel="noopener">${s?.[6]?"Originaldatei öffnen":"Originaldatei öffnen"} ↗</a><p>${s?.[6]?"Die Originaldatei dieses Buches ist direkt hier hinterlegt. Weitere Fassungen und Audios findest du unten auf der Buchseite.":"Die Originaldatei öffnet sich in einem neuen Tab."}</p></div>`:''}<ol>${(phase===0?l.experiment:phase===1?reading:id==='babel'?['Beschreibe die Ordnung der Bibliothek. Notiere eine konkrete Textstelle.','Erkläre den Unterschied zwischen vollständigem Bestand und Verstehen. Untersuche auch Wissen, Vermutung und Hoffnung des Erzählers. Belege deine Beobachtungen.','Schreibe unten deine Ergebnisse und eine offene Frage für die Reise auf. Erst danach betrachten wir die Bilder.']:['Erinnere dich an ein konkretes Detail aus dem Versuch oder Bild.','Lies die passende Stelle im Original. Notiere Seite oder Abschnitt.','Schreibe unten deine Beobachtung, den Textbezug und deinen eigenen Gedanken.']).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="librarian-tools">${phase!==1?`<button class="btn" data-guide-focus>${phase===0?"Zum Versuch auf dieser Seite ↓":"Zum Schreibfeld auf dieser Seite ↓"}</button>`:""}<button class="btn secondary small" data-guide-speak>Auftrag vorlesen</button><details><summary>Ein Beispiel, bitte.</summary><p>${esc(l.example)}</p><p>Das ist ein Satzgerüst, keine Musterlösung.</p></details></div>${phase===2&&id!=='babel'?'<div class="actions"><button class="btn secondary" data-guide-book="experiment">Mir fehlt noch der Versuch / das Bild</button><button class="btn secondary" data-guide-book="resource">Mir fehlt noch die Textstelle</button></div>':''}</section>`;}
function librarianBookOutro(id,kind){const l=librarianLessons[id];return `<section class="librarian-next"><b>Herr Dr. Foliants nächster Schritt</b><p>${kind==='experiment'?'Nimm eine konkrete Beobachtung mit. Prüfe sie jetzt am Originaltext.':kind==='resource'?'Halte jetzt mit wenigen eigenen Sätzen fest, was du beobachtet und im Text gefunden hast.':esc(l.bridge)}</p><button class="btn" ${kind==='question'?'data-guide-next-room':`data-guide-book="${kind==='experiment'?'resource':'question'}"`}>${kind==='experiment'?'2 · Zur Originallektüre →':kind==='resource'?'3 · Zum klaren Logbuchauftrag →':id==='future'?'Lesetour abschliessen →':'Mit Foliant zur nächsten Galerie →'}</button></section>`;}

// Hand-picked invitations: these describe the work, rather than inventing a reader profile.
const foliantPicks=[
 {title:'Die Verwandlung',author:'Franz Kafka',tags:['seltsam','kurz'],hook:'Ein Mensch wacht als Ungeziefer auf. Das Unheimlichste ist, wie schnell wieder über Arbeit gesprochen wird.',bait:'Lies den Anfang: Worüber sorgt sich Gregor zuerst?',room:'babel'},
 {title:'Schachnovelle',author:'Stefan Zweig',tags:['spannung','kurz','menschen'],hook:'Ein Schachbrett wird zum Fluchtweg aus der Isolation – und zur Falle im eigenen Kopf.',bait:'Warte auf die Geschichte des Dr. B.: Ab dort verändert sich das Spiel.',room:'attention'},
 {title:"Lewis Carroll: Alice's Abenteuer im Wunderland",author:'Charles Lutwidge Dodgson',tags:['seltsam','witz'],hook:'Hier benehmen sich Wörter wie widerspenstige Tiere. Jede Erklärung kann die nächste Verwirrung auslösen.',bait:'Folge dem Kaninchen. Gib die Suche nach einer vernünftigen Hausordnung ruhig auf.',room:'babel'},
 {title:'Der Hund der Baskervilles',author:'Arthur Conan Doyle',tags:['spannung','welt'],hook:'Ein Moor, ein angeblicher Fluch und ein Hund: Holmes muss herausfinden, wer von der Angst profitiert.',bait:'Behalte die Erklärung des Fluchs im Kopf. Welche Einzelheit macht dich misstrauisch?',room:'bubble'},
 {title:'Die Zeitmaschine',author:'Herbert George Wells',tags:['seltsam','welt','spannung'],hook:'Die Zukunft sieht zunächst sanft aus. Dann fällt auf, wer dort im Licht lebt – und wer darunter.',bait:'Reise erst einmal mit. Die schöne Oberfläche darf dich ruhig täuschen.',room:'future'},
 {title:'Heinrich von Kleist: Michael Kohlhaas',author:'Heinrich von Kleist',tags:['menschen','spannung'],hook:'Zwei Pferde werden zum Anlass eines Aufstands. Ein Mann fordert Recht, bis seine Forderung andere Leben zerstört.',bait:'Achte darauf, wann du Kohlhaas noch recht gibst – und wann du zögerst.',room:'court'},
 {title:'Candide oder der Optimismus',author:'François Marie Arouet de Voltaire',tags:['witz','welt'],hook:'Die beste aller möglichen Welten? Voltaire schickt diese Behauptung durch eine Serie von Katastrophen.',bait:'Lies die ersten Stationen wie einen Streit zwischen Behauptung und Wirklichkeit.',room:'nostalgia'}
];
const foliantMoods={seltsam:'Etwas, das meinen Kopf verdreht',spannung:'Ich will wissen, wie es weitergeht',menschen:'Menschen, die mir nahekommen',witz:'Witz mit Widerhaken',welt:'Eine fremde Welt',kurz:'Heute nur ein kurzer Einstieg'};
function foliantMetadata(book){const title=book.title.toLocaleLowerCase('de'),tags=[];const clues={seltsam:/gespenst|traum|teufel|spuk|zauber|märchen|verwandlung|wunder|zeitmaschine/,spannung:/mord|krimi|detektiv|geheimnis|abenteuer|verbrechen|baskerville|schachnovelle/,menschen:/liebe|leben|familie|freund|frau|mutter|vater|herz/,witz:/satire|humor|komödie|schwank|schelm|narr|optimismus/,welt:/reise|welt|meer|insel|afrika|indien|china|sibirien/,kurz:/gedicht|novelle|fabel|aphorism|kurze|erzählung/};for(const [tag,re]of Object.entries(clues))if(re.test(title))tags.push(tag);return tags;}
function foliantChoose(books,profile){const history=profile.history||[],scores=profile.scores||{},authors=profile.authors||{},seen=new Map();history.forEach(h=>seen.set(h.title,(seen.get(h.title)||0)+1));let best=null;books.forEach((book,index)=>{const curated=foliantPicks.find(p=>p.title===book.title&&p.author===book.author),tags=curated?.tags||foliantMetadata(book),score=tags.reduce((n,t)=>n+(scores[t]||0)+(profile.mood===t?8:0),0)+(authors[book.author]||0)-(seen.get(book.title)||0)*40+(curated?1:0)+(curated?.title==='Die Verwandlung'?1:0);if(!best||score>best.score){const clue=book.title.match(/gespenst\w*|traum\w*|geheimnis\w*|abenteuer\w*|liebe\w*|reise\w*|gedicht\w*|novelle\w*|satire\w*/i)?.[0];best={...book,...curated,index,tags,score,metadataOnly:!curated,hook:curated?.hook||(clue?`„${clue}“ hat meine Hand auf diesem Buchrücken angehalten: ${book.title} von ${book.author}.`:`Mein Fund abseits der bekannten Namen: „${book.title}“ von ${book.author}.`),bait:curated?.bait||(clue?`Der Titel verspricht „${clue}“. Lies den ersten Absatz: Wird dieses Versprechen schon eingelöst oder verschoben?`:`Nimm den Titel „${book.title}“ als erste Vermutung. Nach dem ersten Absatz: Würdest du dem Buch noch denselben Namen geben?`)};}});return best;}

function foliantReason(pick,profile){if(pick.metadataOnly)return `Diesen Vorschlag leite ich aus Titel und Autor ab; eine Inhaltsdeutung behaupte ich hier nicht.${profile.last?' Deine letzte Antwort zu „'+profile.last.title+'“ beeinflusst die Gewichtung.':''}`;const names={seltsam:'verschobene Wirklichkeit',spannung:'Spannung',menschen:'innere Konflikte',witz:'Witz und Widerspruch',welt:'fremde Gesellschaften',kurz:'einen kurzen Einstieg'},last=profile.last,previous=foliantPicks.find(p=>p.title===last?.title),shared=pick.tags.filter(t=>previous?.tags.includes(t));if(last?.answer==='liked')return shared.length?`Nach „${last.title}“ nehme ich ${shared.map(t=>names[t]).join(' und ')} mit. ${pick.title} setzt diese Spur anders fort.`:`„${last.title}“ hat dich gepackt. Jetzt probiere ich bewusst einen Seitenweg: ${pick.tags.map(t=>names[t]).join(' und ')}.`;if(last?.answer==='different')return `„${last.title}“ war nicht dein Ton. Diesmal setze ich auf ${pick.tags.map(t=>names[t]).join(' und ')}; die Eigenschaften des letzten Bands bekommen weniger Gewicht.`;if(last?.answer==='shorter')return 'Heute kein grosser Anlauf: Kafka und Zweig stehen für einen überschaubaren Einstieg bereit. Du musst den Band nicht zu Ende lesen.';if(profile.mood)return pick.tags.includes(profile.mood)?`Du suchst ${names[profile.mood]}. Genau an dieser Spur habe ich diesen Band ausgesucht.`:`Deinen Wunsch habe ich mir gemerkt. Die passenden Bände hattest du schon in der Hand; hier kommt ein Seitenweg mit ${pick.tags.map(t=>names[t]).join(' und ')}.`;return 'Mein erster Griff: Kafka. Der Alltag läuft weiter, obwohl sein Fundament gerade zusammenbricht.';}

// Dramaturgy: fictional speech paraphrases the local originals, never impersonates their authors.
const foliantDrama={
babel:{act:'I · Das Versprechen',title:'Alles vorhanden. Noch nichts gewonnen.',speech:'Willkommen in meiner angeblich perfekten Bibliothek: Jeder Band ist erreichbar. Ich behaupte deshalb, dass hier jeder Mensch gut lesen kann. Du wirst diese Behauptung auf unserer Tour auseinandernehmen. Schon Borges trennt die Fülle der Zeichen vom Finden eines Sinns.',task:'Dreh dich zu einer Bücherwand. Wähle EINEN Rücken, ohne die Suche zu benutzen. Sage dir, warum gerade dieser. Zieh ihn heraus, lies den Anfang und stelle ihn zurück, wenn er dich nicht hält. War die Fülle eine Hilfe oder ein Hindernis?',question:'Was soll diese Bibliothek dir zuerst geben?',options:['Einen Weg durch die Fülle','Die Freiheit, mich zu verlieren'],replies:['Dann schulde ich dir Orientierung. Später prüfst du, ob meine Auswahl dir auch etwas vorenthält.','Dann lasse ich Umwege zu. Später prüfen wir, ob Freiheit ohne Zeit und Hilfe wirklich für alle dieselbe ist.'],voices:[['Setz','Alle Bücher, keine Menschen?','Stell dir vor, die Bibliothek gehörte nur dir. Lies Henry Bemis: Welche Stelle lässt deinen Wunsch kippen?'],['Kinsky','Auch die Welt hat Schriftzüge.','Suche erst ein Detail im Raum. Lies danach „Pfad“: Was lässt sich dort erst mit Erinnerung und Wissen erkennen?']],anchor:'Borges: Anfang und Suche nach sinnvollen Büchern. Amlinger: Bücherberg und Babel-Metapher im Einstieg.'},
attention:{act:'I · Das Versprechen',title:'Ich kann dir Bücher geben. Kann ich dir Zeit geben?',speech:'Amlinger fragt nach den Bedingungen des Lesens, Freiwald unterscheidet Alltagslektüre von langen, schwierigen Texten. Deshalb zählen wir hier keine Seiten. Wir beobachten, was eine Unterbrechung mit einem Gedanken macht.',task:'Vor dem Versuch: Lies einen Absatz eines freien Bands. Leg ihn gedanklich beiseite und schaue drei andere Buchrücken an. Geh zum ersten zurück. Findest du den Gedanken wieder? Im Versuchsbuch kannst du Unterbrechungen auch ausschalten.',question:'Was fehlte dir eher?',options:['Ein ungestörter Moment','Ein Text, der mich festhält'],replies:['Dann ist nicht dein Wille allein das Problem. Nimm diese fehlende Ruhe später mit zur Tür ohne Klinke.','Dann probieren wir später Resonanz. Ein Text kann dich packen; erzwingen kann ich das nicht.'],voices:[['Köck','Zeit ohne Nutzennachweis.','Lies einen Abschnitt ohne Markieren und ohne Antwortpflicht. Darfst du Zeit dafür verbrauchen, auch wenn kein Ergebnis entsteht?'],['Sullivan','Ein Buch als Unterschlupf.','Lies die Campingszene. Vergleiche Ablenkung mit Schutz: Wann brauchst du Abstand zur Welt?']],anchor:'Freiwald, PDF S. 4–6: Tempo und unterschiedliche Arten des Lesens. Amlinger: freie Zeit als soziale Ressource.'},
court:{act:'II · Die Risse',title:'Das Lesen stirbt. Welches Lesen?',speech:'Mein Stempel „Kulturverfall“ ist zu gross. Freiwald bestreitet die universelle lesende Gesellschaft von früher und nimmt heutige Leseschwierigkeiten trotzdem ernst. Amlinger untersucht die Bedingungen einer bestimmten Lesekultur. Das sind unterschiedliche Fragen. Im Gericht muss jede Anklage sagen, wen und welche Praxis sie meint.',task:'Vor den Akten: Formuliere die Anklage mit einer konkreten Gruppe und Leseform. Nach den Akten streiche alles, was du nicht belegen kannst. Keine pauschale Freisprechung, keine pauschale Todesanzeige.',question:'Welche Anklage willst du prüfen?',options:['Lange Texte werden schwieriger','Lesen wird sozial ungleich verteilt'],replies:['Dann brauche ich Belege zu dieser Fähigkeit, nicht bloss weniger verkaufte Papierbücher.','Dann zählen Zeit, Bildung und Lebensbedingungen. Ein offenes Regal allein widerlegt die Anklage nicht.'],voices:[['Zhadan','Was bleibt im Krieg von einer Bibliothek?','Lies die beschädigte Schulbibliothek. Welche Bedeutung hat das Mitnehmen der Gedichtbände, obwohl es Schlimmeres gibt?'],['Nachtwey','Lesen macht noch keine bessere Welt.','Suche die Grenze zwischen Weltvorstellung und Veränderung. Welche Handlung müsste zu deiner Lektüre hinzukommen?']],anchor:'Freiwald, PDF S. 5–11: Kompetenz, Vergleich und Delegation. Amlinger: gleichzeitige Öffnung und neue Ungleichheit.'},
nostalgia:{act:'II · Die Risse',title:'Dieses Regal erinnert sich zu schön.',speech:'Ich habe das Gestern frisch poliert. Früher fürchtete man zu viel Lesen, heute zu wenig: Freiwald stört diese hübsche Erinnerung. Aber Petrowskaja erinnert an Verbote und Weitergabe, Karahasan an die Freiheit des stillen Lesens. Geschichte ist mehr als eine alte Medienpanik.',task:'Wähle einen alten Band aus der Wand. Bevor du ihn öffnest: Wer hätte ihn damals lesen dürfen, gekonnt und bezahlt? Im Museum prüfst du dann, warum vertraute Warnungen so glaubwürdig klingen.',question:'Was fehlt im goldenen Gestern?',options:['Die Menschen ohne Zugang','Die riskanten und freien Lesemomente'],replies:['Merke dir diese unsichtbaren Personen. Die nächste Tür verlangt mehr als einen Schlüssel.','Dann darf Kritik an Nostalgie nicht jede Erinnerung wegwischen. Suche ihre konkreten Bedingungen.'],voices:[['Petrowskaja','Ein weitergereichtes Buch kann gefährlich sein.','Suche die Passage über den Vater und Pasternak. Was verändert sich, wenn Lesen verdächtig ist?'],['Karahasan','Still lesen, bei sich und ausser sich sein.','Lies die Ambrosius-Szene und einen späteren Abschnitt. Was ermöglicht die Stille, das ein öffentliches Urteil nicht erfasst?']],anchor:'Freiwald, PDF S. 2–3 und 6–9: wiederkehrende Ängste und problematische Rückblicke.'},
access:{act:'II · Die Risse',title:'Die Tür steht offen. Wer kommt wirklich hinein?',speech:'Amlinger lässt mich meinen Lieblingssatz zurücknehmen: Mehr Auswahl bedeutet nicht automatisch gleiche Chancen. Lesen kann verbinden und soziale Herkunft sichtbar machen. Für manche beginnt es mit einer freien Stunde, für andere damit, dass jemand mitliest.',task:'Betrachte dieselbe Bücherwand einmal als Mensch mit freiem Nachmittag und einmal als Mensch mit Betreuungspflichten und wenig Übung. Verteilt im Versuch nicht nur Bücher, sondern Zeit, Hilfe und Ruhe. Die Figuren sind ein Gedankenmodell.',question:'Was öffnest du zuerst?',options:['Zeit und einen geschützten Ort','Begleitung und passende Einstiege'],replies:['Gut. Aber Zeit allein hilft nicht jedem Menschen. Prüfe beim Verteilen, wer zusätzliche Unterstützung braucht.','Gut. Aber Begleitung kann nicht jede fehlende Stunde ersetzen. Lass keine Barriere verschwinden, nur weil unser Modell einfach ist.'],voices:[['Reckwitz','Aufmerksamkeit wird gelernt.','Suche den Gedanken vom Lesen als kultureller Praxis. Welche Gewohnheit könnte eine Bibliothek ermöglichen statt voraussetzen?'],['Ernaux','Die Bücherwand verbindet und trennt.','Lies den Besuch der Cousine. Schau dann nochmals unsere Wand an: Einladung oder soziale Grenze?'],['Zambra','Das Kind hilft dem lesenden Vater.','Lies die Szene mit dem französischen Maulwurfbuch. Wer bringt hier wem das Lesen bei?']],anchor:'Amlinger: Anton Reiser, Hilla Palm, soziale Mobilität und freie Zeit; Einstieg und Schluss des lokal gespeicherten Beitrags.'},
delegate:{act:'III · Die Versuchungen',title:'Ich lese für dich. Wem gehört dann dein Urteil?',speech:'Freiwald hält Delegieren nicht pauschal für falsch: Wir müssen nicht jeden Text selbst lesen. Doch irgendjemand liest und wählt für uns. Auch ich, Herr Dr. Foliant, bin ein solcher Filter. Heute findest du heraus, wann du mir vertrauen und wann du mich unterbrechen solltest.',task:'Lies zunächst nur meine Beschreibung eines empfohlenen Bands. Forme eine Erwartung. Zieh den Band heraus und lies selbst einen Absatz. Was konnte meine Beschreibung vermitteln, was begann erst beim Lesen?',question:'Wo willst du selbst nachlesen?',options:['Bei einer entscheidenden Behauptung','Wenn Ton und Erfahrung verloren gehen'],replies:['Dann verlange die überprüfbare Stelle. Ein selbstsicherer Vermittler ist noch kein Beleg.','Dann ersetzt auch eine richtige Zusammenfassung nicht jede Leseerfahrung. Höre auf Rhythmus, Bilder und Pausen.'],voices:[['Singer','Zeichen öffnen immaterielle Wirklichkeiten.','Suche eine Passage über symbolisch vermittelte Wirklichkeit. Was entsteht zwischen Zeichen und deinem eigenen Vorstellen?'],['Maci','Zwei Seiten können zwei Stunden sein.','Lies einen Übergang laut. Fasse ihn zusammen. Was verschwindet zwischen den beiden Fassungen?']],anchor:'Freiwald, PDF S. 9–11: Delegation, Vertrauen und ungleich verteilte Lesefähigkeit; Engemann als weitere Gegenposition.'},
bubble:{act:'III · Die Versuchungen',title:'Mein guter Geschmack ist eine Auswahlmaschine.',speech:'Du hast mir schon Wünsche gegeben. Ich gewichte Titel, Autoren und deine Antworten. Das macht mich hilfreich und begrenzt meinen Blick. Amlingers offenere Geschmacksordnungen beseitigen Unterschiede nicht einfach. Heute darfst du meinen Kompass absichtlich stören.',task:'Nimm eine Empfehlung an oder lehne sie ab. Schau auf die begründete nächste Wahl. Zieh danach mit der Regalsuche einen Band von einem dir unbekannten Autor heraus. Der Zufallsweg ist kein Auftrag für dieses freie Werk; Zurückstellen ist erlaubt.',question:'Wie soll ich dich jetzt begleiten?',options:['An meinem Geschmack anknüpfen','Meine Gewohnheit unterbrechen'],replies:['Dann benenne ich meine Auswahlgründe. Du prüfst, was dadurch immer wieder fehlt.','Dann such dir gerade keinen vertrauten Namen. Ein fremder Rücken garantiert aber noch keine fremde Sicht.'],voices:[['Habermas','Mehr als ein nützlicher Informationskanal.','Suche gegen Ende den Gedanken zur literarischen Erfahrung. Was würde eine reine Informationsauswahl übersehen?']],anchor:'Amlinger: Vielfalt der Genres und fortbestehende Distinktion. Freiwald: Wer liest und auswählt, wenn andere delegieren?'},
bookish:{act:'III · Die Versuchungen',title:'Du siehst eine Bibliothek. Siehst du Leser?',speech:'Amlinger beginnt mit angesammelten Büchern. Hagner zeigt einen Leser, dem der bürgerliche Blick das Lesen kaum zutraut. Die schöne Wand hinter mir beweist gar nichts über dich. Auch unsere Inszenierung kann zum blossen Bücherbild werden.',task:'Schau zehn Sekunden auf diese Wand, ohne einen Band zu öffnen. Danach lies zehn Sekunden in einem Band. Halte fest, was auf einem Foto der Bibliothek von diesen beiden Momenten zu unterscheiden wäre.',question:'Was soll dein Bücherbild zeigen?',options:['Zugehörigkeit und Geschmack','Eine konkrete Leseerfahrung'],replies:['Das ist nicht verboten. Aber wer fühlt sich von diesem Zeichen ausgeschlossen?','Dann zeig auch die Unsicherheit, Unterbrechung oder Freude, die kein prachtvoller Rücken verrät.'],voices:[['Hagner','Ein Foto ist kein Beweis für gelesene Seiten.','Betrachte Lionel auf der Postkarte. Was weisst du, was vermutest du – und welche Vorurteile stecken darin?'],['Lewitscharoff','Das Leseherz bleibt unsichtbar.','Suche eine körperliche oder emotionale Leseerfahrung. Was kann ein Regalbild davon nicht zeigen?']],anchor:'Amlinger: Besitz, Bookishness und soziale Selbstbilder. Pressman: das Buch als sichtbares kulturelles Objekt.'},
media:{act:'IV · Was beim Lesen geschieht',title:'Der Gedanke wechselt seinen Körper.',speech:'Amlinger verbindet Lesen mit der Anordnung seiner Medien. Diese Bibliothek lenkt deinen Blick ebenfalls: warmes Licht, grosse Wände, meine Stimme. Nun wechseln wir die Form. Kein Werkzeug ist unsichtbar, auch das gedruckte Buch nicht.',task:'Lies denselben Gedanken still und dann laut. Achte auf eine Stelle, an der du anders betonst oder innehältst. In der Stimmenmaschine vergleiche weitere Formen. Es gibt keinen vorgegebenen Sieger.',question:'Worauf hörst du zuerst?',options:['Rhythmus, Stimme und Körper','Was die Form hervorhebt oder abschneidet'],replies:['Dann darf ein Gedicht sich deiner schnellen Zusammenfassung widersetzen.','Dann untersuche auch diese Bibliothek: Was rückt ihr schönes Interieur in den Vordergrund?'],voices:[['Mayröcker','Welt erklären oder Welt zum Klingen bringen?','Lies den kurzen Beitrag laut und still. Lass ein Bild stehen, statt es sofort in eine These zu übersetzen.'],['Beyer','Eine Fähigkeit und ihre Verletzlichkeit.','Suche die Geschichte der Mutter und ihrer Bücher. Was fehlt, wenn nur die Bücher wieder da sind?'],['Mahler','Proust, Comic und ein leeres Notizbuch.','Betrachte PDF-Seite 3. Warum erhält das leere Notizbuch die besten Bewertungen? Was verspottet der Vergleich?']],anchor:'Amlinger: Umblättern, Scrollen und materielle Nähe; Nantke und Kittler: Werkzeuge wirken am Denken mit.'},
resonance:{act:'IV · Was beim Lesen geschieht',title:'Ein fremdes Leben. Meine eigenen Muster.',speech:'Rosa beschreibt, wie narrative Resonanz die Beziehung zur Welt verändern kann. Illouz zeigt auch geliehene Muster, Stepanova die riskante fremde Haut. Ich verspreche dir deshalb keine automatische Empathie. Erst lesen, dann merken, wo du ergänzt und urteilst.',task:'Lies die Szene im Versuch. Sage deine Vermutung laut. Lies nochmals nur das, was wirklich dasteht. Erfinde danach eine Gegenstimme. Hat der Text dich verändert oder hast du ihn in deine alte Geschichte eingepasst?',question:'Was hat dich beim Lesen erwischt?',options:['Ein vertrautes Muster','Etwas, das meinem Muster widerspricht'],replies:['Illouz hilft uns, solche geliehenen Plots zu erkennen. Vertrautheit kann tragen und täuschen.','Bei Rosa kann daraus eine veränderte Weltbeziehung entstehen. Aber eine einzelne Irritation beweist das noch nicht.'],voices:[['Illouz','Liebesgeschichten können Erwartungen vorgeben.','Vergleiche eine der drei Leseweisen mit deinem ersten Urteil. Hat ein geliehener Plot mitgelesen?'],['Cusk','Ernaux verändert den Blick auf das eigene Leben.','Suche eine Stelle, an der eine persönliche Entscheidung gesellschaftlich lesbar wird.'],['Rosa','Verwandlung lässt sich nicht bestellen.','Suche einen Moment narrativer Resonanz. Wann hat dein eigener Text dich erreicht – oder gerade nicht?'],['Stepanova','Die fremde Haut hat einen Rückweg nötig.','Suche ein Beispiel für das Übernehmen einer anderen Sicht. Was macht es möglich, was macht es riskant?']],anchor:'Die vier Essays widersprechen einer einfachen Formel „Lesen macht empathisch“. Ihre Gründe sind persönliche und theoretische Perspektiven.'},
future:{act:'V · Eine andere Bibliothek',title:'Nicht die letzte lesende Person. Die nächste Entscheidung.',speech:'Ich nehme meine erste Behauptung zurück: Vollständige Regale genügen nicht. Freiwald macht aus dem vermeintlichen Untergang eine Aufgabe für Lesefähigkeit; Amlinger verlangt den Blick auf Zeit und soziale Unterschiede. Die Essays geben keine einheitliche Pflicht zum Lesen. Du entscheidest, welche Bibliothek wir daraus machen.',task:'Kehre zu einem freien Band zurück, den du unterwegs gewählt hast. Lies weiter oder stelle ihn bewusst zurück. Verteile danach die 100 Minuten im Versuch: Was willst du selbst lesen, was delegieren, und welche Bedingung willst du für andere verändern?',question:'Welche Regel nimmst du mit?',options:['Selbst prüfen, wo es darauf ankommt','Zeit und Zugang mit anderen teilen'],replies:['Schreibe auf, bei welcher Entscheidung und an welcher Originalstelle du das tun wirst.','Schreibe eine konkrete Handlung auf: mit wem, wann, wo und welche Hilfe. Mehr Bücher allein reicht nicht.'],voices:[['Joas','Viele Bücher oder wenige mehrfach?','Vergleiche zwei Lesezwecke. Deine Regel darf anders ausfallen als die deines Nachbarn.'],['RaabeWegner','Eine Einladung ins Freie.','Lies den Beitrag und prüfe deine Regel: schafft sie Freiraum oder eine neue Leistungspflicht?']],anchor:'Freiwald, PDF S. 9–11; Amlinger, Schluss; die 25 Essays als offene, widersprüchliche Antworten auf „Warum lesen?“.'}
};
function foliantDramaMarkup(id,compact=false){const d=foliantDrama[id],choice=state.data.dramaChoices?.[id];return `<section class="foliant-drama" data-drama-room="${id}"><span class="eyebrow">${esc(d.act)}</span><h3>${esc(d.title)}</h3><button data-foliant-say data-foliant-script="${esc(JSON.stringify([d.speech,d.task,d.question]))}">Foliants Gedanken hören 🔊</button>${compact?`<details><summary>Die Bibliothek als Versuch benutzen</summary><p>${esc(d.task)}</p><small>Foliants freie Rede nach den Originaltexten; keine wörtlichen Zitate.</small></details>`:`<p>${esc(d.speech)}</p><div class="drama-action"><b>Die Bibliothek ist dein Versuch</b><p>${esc(d.task)}</p></div>`}<p><b>${esc(d.question)}</b></p><div class="drama-choices">${d.options.map((o,i)=>`<button data-drama-choice="${i}" aria-pressed="${choice===i}">${esc(o)}</button>`).join('')}</div><p class="drama-reply" aria-live="polite">${choice===undefined?'Deine Antwort ist eine Spur, keine richtige oder falsche Lösung.':esc(d.replies[choice])}</p>${compact?`<p class="drama-shelf-invite">${d.voices.map(([sid,hook])=>{const s=sources.find(s=>s[0]===sid);return `<button data-drama-source="${sid}">${esc(s[1].split(' · ')[0])}: ${esc(hook)} →</button>`;}).join('')}</p>`:`<details class="drama-voices" open><summary>Stimmen aus den Regalen · ${d.voices.length}</summary>${d.voices.map(([sid,hook,impulse])=>{const s=sources.find(s=>s[0]===sid);return `<article><span class="eyebrow">${esc(s[1].split(' · ')[0])}</span><h4>${esc(hook)}</h4><p>${esc(impulse)}</p><button data-foliant-say data-foliant-script="${esc(JSON.stringify([hook,impulse]))}">Leseimpuls hören 🔊</button><button data-drama-source="${sid}">Diesen Essay aus dem Regal ziehen →</button></article>`;}).join('')}</details><details><summary>Woher Foliants Gedanken kommen</summary><p>${esc(d.anchor)}</p><p>Foliants Rede ist eine freie Paraphrase und unsere Inszenierung, kein wörtliches Zitat. Die Bücher oben enthalten die gesondert hinterlegten Originaldateien.</p><div class="actions">${['Freiwald','Amlinger'].map(sid=>`<button data-drama-source="${sid}">${sid==='Freiwald'?'Freiwald':'Amlinger'} im Original →</button>`).join('')}</div></details>${id==='future'?`<div class="drama-return"><h4>Deine Spur durch die Bibliothek</h4>${Object.entries(foliantDrama).map(([rid,r])=>{const c=state.data.dramaChoices?.[rid];return c===undefined?'':`<p><b>${esc(r.title)}</b><br>${esc(r.options[c])}</p>`;}).join('')||'<p>Du kannst auch ohne ausgewählte Antworten einen eigenen Weg entwerfen.</p>'}<p>Welche frühere Antwort würdest du jetzt ändern? Begründe die Änderung im Logbuch mit einer Erfahrung und einer Originalstelle.</p></div>`:''}`}</section>`;}
function bindFoliantDrama(root,openSource){root.querySelectorAll('[data-drama-choice]').forEach(b=>b.onclick=()=>{const box=b.closest('[data-drama-room]'),id=box.dataset.dramaRoom,c=Number(b.dataset.dramaChoice);state.data.dramaChoices||={};state.data.dramaChoices[id]=c;save();box.querySelectorAll('[data-drama-choice]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.dramaChoice)===c));box.querySelector('.drama-reply').textContent=foliantDrama[id].replies[c];BabelAudio.auto(foliantDrama[id].replies[c]);});root.querySelectorAll('[data-drama-source]').forEach(b=>b.onclick=()=>openSource(b.dataset.dramaSource));}
// Keep the original experiment instructions; give their transitions a shared dramatic question.
for(const [id,d] of Object.entries(foliantDrama)){librarianLessons[id].hello=d.speech;librarianLessons[id].bridge=id==='future'?'Unsere Bibliothek bleibt offen. Deine Regeln dürfen sich beim nächsten Buch verändern.':`${d.title} Deine Antwort bleibt eine vorläufige Spur. In der nächsten Galerie prüfen wir die nächste Bedingung des Lesens.`;}
librarianLessons.babel.reading[0]='Öffne das lokal hinterlegte Borges-PDF. Lies den Anfang und die passende Stelle zu deinem Bildmotiv.';
librarianLessons.attention.source='Freiwald';librarianLessons.attention.reading=['Lies Freiwald, PDF S. 4–6: Tempo und unterschiedliche Arten des Lesens.','Vergleiche deinen Versuch mit der Unterscheidung zwischen Alltagslektüre und längeren, anspruchsvollen Texten.','Lies Köck als Gegenstimme zur Vorstellung, jede Lesezeit müsse einen messbaren Ertrag haben.'];
librarianLessons.delegate.source='Freiwald';librarianLessons.delegate.reading=['Lies Freiwald, PDF S. 9–11 über Delegation.','Welche Vermittlung ist sinnvoll, wann entstehen Abhängigkeiten? Suche eine konkrete Stelle.','Vergleiche mit Engemanns „Ein Neues Latein“: Wo unterscheiden sich die Diagnosen?'];
librarianLessons.bookish.source='Amlinger';librarianLessons.bookish.reading=['Öffne Amlingers lokal hinterlegten Text oder das Audio.','Suche Bücherbesitz, Bookishness und die Bedingungen freier Lesezeit.','Vergleiche mit Hagners Leser-Porträt: Was beweist das sichtbare Buch, was nicht?'];
librarianLessons.future.prompt='Welche Antwort aus deiner Tour würdest du ändern? Nenne den Ausgangsgedanken, eine konkrete Erfahrung und eine Originalstelle bei Freiwald, Amlinger oder einem Essay. Formuliere danach eine umsetzbare Regel für dich und eine Handlung, die jemand anderem Lesen ermöglicht.';

function foliantDramaJournal(){const entries=Object.entries(foliantDrama).filter(([id])=>state.data.dramaChoices?.[id]!==undefined);return entries.length?`<section class="journal-entry"><h3>Meine Entscheidungen auf der Tour</h3><p>Vorläufige Antworten, keine Leistungswerte.</p>${entries.map(([id,d])=>`<p><b>${esc(d.title)}</b><br>${esc(d.options[state.data.dramaChoices[id]])}</p>`).join('')}</section>`:'';}
function foliantDramaExport(){return Object.entries(foliantDrama).filter(([id])=>state.data.dramaChoices?.[id]!==undefined).map(([id,d])=>d.title+'\n'+d.options[state.data.dramaChoices[id]]).join('\n\n');}
const foliantTransitions={babel:'Ein Regal voller Texte gibt dir noch keinen zusammenhängenden Gedanken. Als Nächstes zerbrechen wir einen Satz.',attention:'Fehlte dir Ruhe oder ein packender Text? Nimm den Unterschied mit ins Gericht: Eine Erfahrung ist noch keine Diagnose für alle.',court:'Welche Art des Lesens hast du angeklagt? Jetzt testen wir, wie das angeblich goldene Gestern diese Anklage färbt.',nostalgia:'Wer fehlt in deiner Erinnerung? Diese Menschen stehen jetzt vor der Tür ohne Klinke.',access:'Zeit und Begleitung sind knapp. Gleich biete ich dir an, für dich zu lesen. Prüfe meinen Preis.',delegate:'Du weisst jetzt, wann du einem Vermittler vertrauen willst. Gleich lernst du, wie deine Wünsche seine Auswahl verändern.',bubble:'Habe ich deinen Geschmack bestätigt oder gestört? Jetzt prüfen wir, was dein sichtbares Bücherbild anderen verspricht.',bookish:'Das Regalbild konnte deine Lektüre nicht beweisen. Nun wechseln wir vom sichtbaren Buch zum Klang und Rhythmus der Zeichen.',media:'Welche Form hat deinen Gedanken verändert? Gleich prüfen wir, ob ein Text auch deinen Blick auf einen Menschen verändert.',resonance:'Vertrautes Muster oder Irritation? Nimm beides mit. Im letzten Raum entscheidest du, welche Bedingungen dein künftiges Lesen braucht.'};
for(const [id,bridge]of Object.entries(foliantTransitions))librarianLessons[id].bridge=bridge;

for(const [id,d]of Object.entries(foliantDrama))if(id!=='future')librarianLessons[id].prompt+=` Zur Raumfrage „${d.question}“: Bleibst du bei deiner Antwort oder änderst du sie? Begründe das mit deinem Erlebnis in der Bibliothek und einer konkreten Stelle aus einem der hier angebotenen Originaltexte.`;

// The journey begins in the literary original, before its staged interpretation.
librarianLessons.babel.hello='Bevor wir durch meine Bibliothek reisen, lesen wir Borges. Lies zuerst die ganze Erzählung „Die Bibliothek von Babel“. Danach untersuchen wir ihre Ordnung, die Suche nach Sinn und den Erzähler. Meine Bilder kommen erst anschliessend: Sie sind eine Deutung, die du am Text prüfen sollst.';
librarianLessons.babel.reading=['Öffne das Borges-PDF und lies die gesamte Erzählung zunächst ohne die Bildfolge. Notiere eine erste Irritation oder Frage.','Lies gezielt noch einmal: Wie ist die Bibliothek aufgebaut? Was folgt aus der Behauptung, dass sie alle möglichen Bücher enthält? Suche zu beiden Fragen eine konkrete Textstelle.','Untersuche den Erzähler: Was weiss er, was vermutet oder glaubt er? Wähle eine Stelle zur Suche nach Sinn und eine zum Umgang der Menschen mit der Bibliothek.'];
librarianLessons.babel.prompt='Halte dein Borges-Studium fest: 1. Beschreibe die Ordnung der Bibliothek mit einer Textstelle. 2. Erkläre, warum vollständiger Bestand noch kein Verstehen bedeutet, und belege das am Text. 3. Unterscheide an einer Stelle Wissen, Vermutung oder Hoffnung des Erzählers. Ergänze eine offene Frage, die du auf die Reise mitnimmst. Seitenzahlen oder kurze Textanfänge genügen als Belege.';
librarianLessons.babel.example='„Die Bibliothek ist … Die Stelle auf Seite … zeigt … Obwohl alle Bücher vorhanden sind, … Der Erzähler weiss / vermutet / hofft hier … Meine offene Frage lautet …“';
librarianLessons.babel.experiment=['Du hast Borges gelesen und untersucht. Gehe jetzt durch die fünf Bilder. Wähle ein Detail, das du aus dem Text wiedererkennst.','Vergleiche das Bild mit deiner notierten Textstelle: Was stellt unsere Inszenierung dar, was ergänzt oder verändert sie?','Durchsuche ein zufälliges Regal. Nimm deine offene Borges-Frage mit in die nächste Galerie.'];
librarianLessons.babel.bridge='Jetzt beginnt die Reise aus Borges heraus: Seine Bibliothek enthält alles, doch ihre Bewohner finden nicht ohne Weiteres Sinn. In der nächsten Galerie prüfen wir eine erste Bedingung dafür – Aufmerksamkeit.';
foliantDrama.babel.speech=librarianLessons.babel.hello;
foliantDrama.babel.task='Zuerst das Original vollständig lesen und mit Textbelegen studieren. Erst danach die Bücherwände und Bilder mit Borges vergleichen. Deine offene Frage begleitet die ganze Tour.';
function foliantPhaseOrder(id){return id==='babel'?['resource','question','experiment']:['experiment','resource','question'];}

const foliantDebates=[
{title:'Verlernen wir das Lesen?',claim:'Mein erster Einwand gegen den Untergang lautet: Welches Lesen meinst du – Nachrichten, Romane, schwierige Argumente? Mit Freiwald bestreite ich die goldene Vergangenheit einer Gesellschaft, in der alle vertieft gelesen hätten. Mit Amlinger nehme ich trotzdem ernst, dass eine bestimmte literarische Praxis ihre sozialen Bedingungen verändern kann.',a:'Freiwald, PDF S. 5–9: Lesearten, Kompetenzprobleme und historische Vergleiche.',b:'Amlinger: Einstieg zur postliterarischen Diagnose; Schluss zu Demokratisierung und Ungleichheit.',options:['Aber lange Texte fallen vielen schwerer.','Der Zugang war früher auch ungleich.'],replies:['Das ist ein ernst zu nehmender Einwand. Freiwald erkennt Kompetenzprobleme ausdrücklich an. Ich brauche jedoch einen vergleichbaren Befund für dieselbe Leseform und Gruppe. Amlinger ergänzt die Frage nach den Lebensbedingungen. Welche Beobachtung belegt eine Fähigkeit, welche nur fehlende Gelegenheit?','Genau. Daraus folgt aber nicht, dass heutige Ungleichheit harmlos ist. Bei Amlinger können breitere Auswahl und soziale Trennung gleichzeitig wachsen. Welche Gruppe wäre in unserer Bibliothek trotz offener Regale benachteiligt?'],challenge:'Welche konkrete Leseform und welche Menschen betrifft deine Diagnose? Nenne einen Beleg und eine Grenze des Vergleichs.'},
{title:'Ist Lesen eine Frage des Willens?',claim:'Ich verteile ungern Durchhalteparolen. Amlinger erinnert mich daran, dass freie Zeit und Ressourcen ungleich verteilt sind. Freiwald lässt mich zugleich unterscheiden: viel Alltagslektüre bedeutet noch nicht, einen langen Gedankengang verfolgen zu können. Unsere Bücherwand kann weder Übung noch Ruhe ersetzen.',a:'Freiwald, PDF S. 4–6: Tempo, komplexe Texte und verschiedene Lesepraxen.',b:'Amlinger: freie Lesezeit, Betreuung und soziale Ressourcen.',options:['Man muss sich eben konzentrieren.','Man muss zuerst Zeit und Unterstützung schaffen.'],replies:['Übung und bewusste Entscheidungen helfen. Aber wem steht ein ungestörter Nachmittag überhaupt zur Verfügung? Mit Amlinger widerspreche ich, sobald Willenskraft eine fehlende soziale Ressource ersetzen soll. Welche Hilfe könnte Konzentration erst möglich machen?','Da gehe ich mit. Doch Zeit allein garantiert noch kein Verstehen. Mit Freiwald frage ich zusätzlich nach Lesefähigkeit und Förderung. Wie würdest du freie Zeit, passende Texte und Begleitung verbinden?'],challenge:'Entwirf eine konkrete Hilfe für eine Person aus dem Tür-Versuch. Was leistet sie – und was noch nicht?'},
{title:'Darf ich das Lesen delegieren?',claim:'Ja, ich darf für dich vorauswählen – aber ich schulde dir Gründe und Originalstellen. Freiwald betrachtet Delegieren nicht pauschal als Verfall. Seine Frage nach Vertrauen trifft mich selbst. Amlingers Blick auf knappe Zeit macht die bequeme Abkürzung verständlich; sie entbindet mich nicht davon, meine Auswahl offenzulegen.',a:'Freiwald, PDF S. 9–11: delegiertes Lesen, Vertrauen und die weiterhin lesenden Vermittler.',b:'Amlinger: soziale Bedingungen freier Zeit. Die Verbindung zur Delegation ziehen wir hier als eigene Schlussfolgerung.',options:['Eine gute Zusammenfassung genügt mir.','Ich will alles selbst im Original lesen.'],replies:['Für welchen Zweck? Eine Orientierung kann genügen. Bei einer entscheidenden Behauptung verlange ich mit Freiwald die überprüfbare Stelle. Ton und Erfahrung können selbst in einer korrekten Kurzfassung fehlen. Wo würdest du meine Vermittlung unterbrechen?','Das ist ein Anspruch, den ich respektiere. Er kostet aber Zeit, die nicht allen gleich zur Verfügung steht. Welche Entscheidung verdient deine eigene Lektüre, und welche Vermittlung könntest du mit offengelegten Quellen verantworten?'],challenge:'Bestimme einen Fall, in dem du delegierst, und einen, in dem du selbst nachliest. Begründe die Grenze.'},
{title:'Beweisen volle Regale eine Lesekultur?',claim:'Meine prachtvollen Wände schmeicheln mir. Amlinger zwingt mich jedoch, Besitz, Selbstdarstellung und Lektüre auseinanderzuhalten. Freiwald stört zusätzlich die Gleichung zwischen Papierbüchern und allem Lesen. Eine digitale Lektüre wird auf meinem schönen Regalfoto unsichtbar.',a:'Freiwald, PDF S. 5–8: Leseformen und problematische Messungen oder Vergleiche.',b:'Amlinger: Bücherberg, Bookishness, Geschmack und soziale Unterschiede.',options:['Bücher sichtbar zu machen lädt zum Lesen ein.','Das ist vor allem eine Statuskulisse.'],replies:['Das kann stimmen. Materialnähe und Zugehörigkeit können Lust wecken. Mit Amlinger frage ich trotzdem: Wen lädt dieses Bild ein, wen schreckt es ab? Und mit Freiwald: Welche wirkliche Lektüre bleibt darin unsichtbar?','Auch das ist möglich. Aber ich würde nicht jedes schöne Bücherbild verurteilen. Welche beobachtbare Handlung unterscheidet hier eine Einladung von einer blossen Kulisse? Denk an Herausziehen, Lesen, Zurückstellen und gemeinsame Zeit.'],challenge:'Verändere eine Regel unserer Bibliothek so, dass aus sichtbarem Bestand eine tatsächliche Lesegelegenheit wird.'},
{title:'Macht Lesen uns automatisch freier?',claim:'Ich verspreche keine moralische Veredelung durch Bücher. Amlinger zeigt Lesen als Möglichkeit sozialen Aufstiegs und zugleich als Trennung von Herkunft und anderen Menschen. Freiwald gibt mir einen praktischen Auftrag: Lesefähigkeit fördern, statt den Untergang zu beklagen. Die Essays prüfen, was daraus im einzelnen Leben wird.',a:'Freiwald, PDF S. 9–11: Förderung und Verantwortung statt Fatalismus.',b:'Amlinger: Anton Reiser, Hilla Palm und der Zusammenhang von Teilhabe und Klassenunterschieden.',options:['Lesen eröffnet andere Leben und Möglichkeiten.','Lesen kann auch isolieren und ausschliessen.'],replies:['Ja. Aber diese Öffnung ist kein Automatismus. Ernaux erzählt zugleich vom Verbinden und Trennen; Rosa von einer möglichen Veränderung der Weltbeziehung. Welche konkrete Textstelle verändert deinen Blick, und welche soziale Bedingung braucht diese Erfahrung?','Ja. Setz und Ernaux halten meinem Enthusiasmus einen Spiegel vor. Das ist kein Grund, Lesen aufzugeben. Mit Amlinger frage ich, wie Lektüre und Zugehörigkeit zusammengehen könnten. Mit Freiwald suche ich eine konkrete Möglichkeit, jemanden zum Lesen zu befähigen.'],challenge:'Welche Handlung könnte zu deinem Lesen hinzukommen, damit eine persönliche Möglichkeit auch anderen offensteht?'}
];
function foliantDebateMarkup(){const n=state.data.lesesaalTopic||0;if(n===0)return `<label for="lesesaal-topic">Gespräch wählen</label><select id="lesesaal-topic">${foliantDebates.map((x,i)=>`<option value="${i}">${esc(x.title)}</option>`).join('')}</select>`+foliantReadingDiscussionMarkup();const d=foliantDebates[n],entry=state.data.lesesaal?.[n];return `<section class="foliant-drama foliant-lesesaal"><span class="eyebrow">Lesesaal · Gespräch mit Herrn Dr. Foliant</span><h3>Widersprich mir.</h3><button data-foliant-say data-foliant-script="${esc(JSON.stringify([d.title,d.claim,d.a,d.b]))}">Foliants Position hören 🔊</button><p>Meine Positionen entstehen im Gespräch mit Freiwald und Amlinger. Ich sage dazu, wo die Texte enden und meine Schlussfolgerung beginnt. Hier gibt es keine Punkte und keine vorgegebene Zustimmung.</p><label for="lesesaal-topic">Worüber diskutieren wir?</label><select id="lesesaal-topic">${foliantDebates.map((x,i)=>`<option value="${i}" ${i===n?'selected':''}>${esc(x.title)}</option>`).join('')}</select><h4>${esc(d.title)}</h4><p><b>Herr Dr. Foliant:</b> ${esc(d.claim)}</p><div class="drama-action"><b>Meine Grundlage</b><p>${esc(d.a)}</p><p>${esc(d.b)}</p><p>Freie Paraphrasen und begründete Verknüpfungen, keine wörtlichen Zitate und keine gemeinsame Position beider Autoren.</p><button data-debate-source="Freiwald">Freiwald selbst prüfen →</button><button data-debate-source="Amlinger">Amlinger selbst prüfen →</button></div><p><b>Halte mir einen Einwand entgegen:</b></p><div class="drama-choices">${d.options.map((o,i)=>`<button data-debate-answer="${i}" aria-pressed="${entry?.choice===i}">${esc(o)}</button>`).join('')}</div><p id="lesesaal-reply" class="drama-reply" aria-live="polite">${entry?.choice===undefined?'Wähle einen Einwand als Gesprächsanfang. Deine eigene Position kann von beiden abweichen.':esc(d.replies[entry.choice])}</p><label for="lesesaal-note"><b>Deine Antwort auf meine Nachfrage</b><br>${esc(d.challenge)}</label><textarea id="lesesaal-note" rows="5" placeholder="Mein Argument. Meine Textstelle. Was ich Foliant entgegenhalte.">${esc(entry?.note||'')}</textarea><button class="btn" id="lesesaal-save">Gespräch im Logbuch festhalten</button><p id="lesesaal-status" role="status"></p><p>Ich reagiere auf den gewählten Einwand mit vorbereiteten, textbezogenen Gegenfragen. Deinen freien Text speichere ich für die Reflexion; ich werte ihn nicht automatisch aus.</p></section>`;}
function foliantDebateJournal(){return foliantTrialJournal()+ ((state.data.readingConversation||[]).map(t=>`<article class="journal-entry"><h3>Lesesaal · ${esc(foliantConversationTopics[t.topic].label)}</h3><p><b>Ich:</b> ${esc(t.text)}</p><p><b>Herr Dr. Foliant:</b> ${esc(t.reply)}</p><p>${esc(t.question)}</p><p>Freiwald · PDF S. ${esc(t.page)}</p></article>`).join(''))+(state.data.readingDiscussion?.length||state.data.readingDiscussionNote?`<article class="journal-entry"><h3>Verlernen wir das Lesen? · Gespräch mit Dr. Foliant</h3>${(state.data.readingDiscussion||[]).map((t,i)=>`<p><b>Ich:</b> ${esc(foliantReadingRounds[i].options[t.choice])}</p><p><b>Dr. Foliant:</b> ${esc(foliantReadingRounds[i].replies[t.choice])}</p>`).join('')}<pre>${esc(state.data.readingDiscussionNote||'')}</pre></article>`:'')+Object.entries(state.data.lesesaal||{}).filter(([,e])=>e.note).map(([n,e])=>`<article class="journal-entry"><span class="eyebrow">Diskussion im Lesesaal</span><h3>${esc(foliantDebates[n].title)}</h3><p>${esc(foliantDebates[n].claim)}</p>${e.choice===undefined?'':`<p><b>Mein Einwand:</b> ${esc(foliantDebates[n].options[e.choice])}</p><p><b>Foliants Nachfrage:</b> ${esc(foliantDebates[n].replies[e.choice])}</p>`}<pre>${esc(e.note)}</pre></article>`).join('');}

// Audio follows the same recommendation and feedback, using complete recorded phrases.
const foliantAudioWelcome='Hier spricht Herr Dr. Foliant. Ich begleite dich durch die Bibliothek. Du kannst meine Stimme jederzeit wieder ausschalten.';
const foliantAudioBrowse='Hier stehen freie Werke neben den Büchern der Lesetour. Zieh einen Band heraus. Die freien Werke haben keine Aufträge.';
const foliantAudioReasons={seltsam:'Du suchst eine verschobene Wirklichkeit. Darauf achte ich bei meinem nächsten Griff.',spannung:'Du suchst Spannung. Ich suche nach einem Einstieg, der eine Frage offenhält.',menschen:'Du suchst Menschen, die dir nahekommen. Achte darauf, wann Nähe entsteht und wann du Abstand hältst.',witz:'Du suchst Witz mit Widerhaken. Prüfe, gegen wen sich der Witz richtet.',welt:'Du suchst eine fremde Welt. Lass dich hineinziehen und prüfe ihre Regeln.',kurz:'Heute genügt ein kurzer Einstieg. Du darfst den Band jederzeit zurückstellen.'};
const foliantAudioFeedback={liked:'Dein letzter Band hat dich gepackt. Diese Spur bekommt bei meiner nächsten Auswahl mehr Gewicht.',different:'Der letzte Band war nicht dein Ton. Seine Eigenschaften bekommen weniger Gewicht; ich probiere einen anderen Zugang.',shorter:'Du möchtest etwas Kürzeres. Ich berücksichtige das beim nächsten Griff.',unread:'Du musst nicht antworten und nicht zu Ende lesen. Wir dürfen einfach einen anderen Band versuchen.'};
const foliantAudioDiscovery=['Dieser Fund kommt aus dem ganzen Katalog. Ich wähle ihn nach Titel, Autor und deinen Antworten aus; eine Inhaltskenntnis behaupte ich hier nicht.','Lies den ersten Absatz. Welche Erwartung weckt der Titel, und was macht der Text daraus?'];
const foliantAudioClues={gespenst:'Am Titel hält mich das Gespenstische fest. Lies den Anfang: Wird die Unruhe erklärt oder erst verstärkt?',traum:'Im Titel begegnet mir das Traumhafte. Schau im ersten Absatz, wie sicher die Wirklichkeit dort noch ist.',geheimnis:'Der Titel verspricht ein Geheimnis. Prüfe beim Einstieg, wer etwas weiss und wer im Dunkeln bleibt.',abenteuer:'Der Titel kündigt ein Abenteuer an. Achte im ersten Absatz darauf, was eine Figur aus ihrer vertrauten Welt lockt.',liebe:'Das Wortfeld Liebe hält meine Hand am Buchrücken an. Lies den Einstieg: Wer spricht über wen, und mit welchem Abstand?',reise:'Der Titel schickt uns auf eine Reise. Achte zuerst auf den Blick der reisenden Person, nicht nur auf das Ziel.',gedicht:'Hier lockt mich das Gedicht. Lies ein paar Zeilen langsam; hör darauf, wo der Rhythmus deine Erwartung verschiebt.',novelle:'Im Titel steht die Novelle. Suche beim Einstieg eine Einzelheit, die mehr verspricht, als sie zunächst erklärt.',satire:'Der Titel kündigt Satire an. Prüfe im ersten Absatz, wer sich lächerlich macht und wer darüber lachen darf.'};
function foliantRecommendationSpeech(pick,profile){const curated=foliantPicks.find(p=>p.title===pick.title&&p.author===pick.author),clue=pick.title.toLocaleLowerCase('de').match(/gespenst|traum|geheimnis|abenteuer|liebe|reise|gedicht|novelle|satire/)?.[0];return [profile.last&&foliantAudioFeedback[profile.last.answer],profile.mood&&foliantAudioReasons[profile.mood],...(curated?[curated.title+' von '+curated.author+'.',curated.hook,curated.bait]:[foliantAudioDiscovery[0],foliantAudioClues[clue]||foliantAudioDiscovery[1]])].filter(Boolean);}

const foliantReadingRounds=[
{question:'Wenn du sagst: Wir verlernen das Lesen – was genau geht verloren?',page:'5',basis:'Freiwald unterscheidet alltägliches Entziffern von längerem, konzentriertem Lesen komplexer Texte. Viel Bildschirmtext widerlegt deshalb noch keine Krise des vertieften Lesens.',options:['Die Fähigkeit, lange Argumente zu verstehen.','Die Lust und Zeit für Bücher.','Schon grundlegendes Textverständnis.'],replies:['Dann prüfen wir Verstehen statt bloss Buchkäufe. Kann jemand den Gedankengang wiedergeben und einen Einwand formulieren? Deine eigene Ungeduld ist ein Anlass zum Prüfen, noch kein Bevölkerungsbefund.','Dann unterscheide bitte Können und Gelegenheit. Wer abends erschöpft ist, hat nicht automatisch eine Fähigkeit verloren. Welche Bedingungen würden dieser Person eine halbe Stunde Lektüre ermöglichen?','Das ist eine konkrete und ernste Diagnose. Freiwald erkennt geringe Kompetenzen ausdrücklich als Krise an. Lass uns dafür die Befunde auf den nächsten Seiten prüfen.']},
{question:'Welche Art von Beleg würde deine Diagnose tragen?',page:'5–6',basis:'Der Text nennt standardisierte Kompetenzstudien und zugleich gegenläufige Befunde zum Lesen aus Vergnügen. Diese Befunde messen unterschiedliche Dinge; sie heben sich nicht einfach gegenseitig auf.',options:['Meine Erfahrung: Ich halte lange Texte kaum noch aus.','Die im Artikel angeführten Kompetenzstudien.','Wie häufig Menschen Bücher lesen.'],replies:['Deine Erfahrung nehme ich ernst. Aber sie sagt zunächst etwas über dich und deine Situation. Versuch denselben Absatz einmal ohne Benachrichtigungen: Was ändert sich? Für eine allgemeine Diagnose brauchen wir zusätzlich vergleichbare Daten.','Das ist näher an einer prüfbaren Kompetenzdiagnose. Notiere aus Freiwalds Text die untersuchte Gruppe und die gemessene Fähigkeit. Was lässt sich daraus sagen – und was noch nicht über alle Menschen und alle Formen des Lesens?','Häufigkeit kann Interesse zeigen. Sie beweist aber weder Verständnis noch dessen Verlust. Freiwalds gegenläufige Befunde sollen die pauschale Untergangsthese stören, nicht Kompetenzprobleme wegzaubern.']},
{question:'Ist die frühere Lesekultur unser verlässlicher Massstab?',page:'2–3 und 6–9',basis:'Freiwald erinnert an frühere Warnungen vor zu viel und falschem Lesen. Die angeblich allgemein vertieft lesende Gesellschaft bleibt ein problematisches Idealbild. Wiederholte Fehlalarme schliessen eine heutige Krise dennoch nicht aus.',options:['Früher konnten alle noch konzentriert lesen.','Die alte Lesekultur war ebenfalls ungleich.','Diesmal sind die neuen Medien wirklich anders.'],replies:['Da klopfe ich mit meinem Katalogstock auf den Tisch: Wer sind alle, und wann ist früher? Such im Text, wer früher vom Lesen ausgeschlossen oder für seine Lektüre getadelt wurde. Ein schönes Bild vom Gestern ist noch kein Vergleich.','Damit korrigierst du den Massstab. Aber Vorsicht: Alte Ungleichheit macht heutige Probleme nicht harmlos. Welche konkrete Gruppe braucht heute Unterstützung, und worin besteht ihre Hürde?','Das ist möglich. Freiwald lässt diese Möglichkeit ausdrücklich offen. Welche veränderte Praxis meinst du: Zeitkonkurrenz durch Videos, unterbrochene Aufmerksamkeit oder ausgelagertes Lesen? Benenne einen Mechanismus statt nur ein Gerät.']},
{question:'Was folgt daraus für uns in dieser Bibliothek?',page:'9–11',basis:'Freiwald behandelt auch delegiertes Lesen und die Vertrauensfrage. Sein praktischer Schluss richtet den Blick auf Lesefähigkeit und Förderung. Die folgenden Vorschläge sind unsere Anwendungen dieses Gedankens.',options:['Zusammenfassungen helfen; ich prüfe entscheidende Stellen selbst.','Ich reserviere ungestörte Zeit für einen schwierigen Text.','Ich will Menschen beim grundlegenden Lesen unterstützen.'],replies:['Ein brauchbarer Vertrag. Wer fasst zusammen, und warum vertraust du ihm? Auch mir solltest du widersprechen dürfen. Wähle jetzt eine Behauptung aus unserem Gespräch und überprüfe ihre Grundlage in Freiwalds Original.','Mach den Versuch klein und beobachtbar: ein Absatz, eine eigene Zusammenfassung, eine offene Frage. Dann lies nochmals. Was verstehst du beim zweiten Durchgang, das dir zuerst entgangen ist? Das ist eine Übung, kein Beweis über die ganze Gesellschaft.','Dann endet unser Gespräch bei einer Handlung. Wen möchtest du unterstützen, mit welchem passenden Text und welcher Begleitung? Beschreibe eine konkrete Lesegelegenheit, die Zugang und Übung tatsächlich ermöglicht.']}
];
const foliantConversationTopics={
attention:{label:'Aufmerksamkeit und Bildschirm',pattern:/handy|smartphone|bildschirm|scroll|konzent|ablenk|aufmerksam|benachrichtig/i,page:'5–6',reply:'Wenn du Unterbrechungen beobachtest, müssen wir zwei Erklärungen auseinanderhalten: Ist das Verstehen verlernt, oder wird es unter diesen Bedingungen nicht ausgeübt? Freiwalds Unterscheidung der Leseweisen hilft hier. Ich würde dieselbe Person denselben schwierigen Absatz unter anderen Bedingungen lesen lassen.',question:'Was geschieht bei dir ohne Benachrichtigungen? Kannst du einen Gedankengang dann wiedergeben, oder bleibt die Schwierigkeit bestehen?'},
access:{label:'Zeit, Bildung und Zugang',pattern:/zeit|erschöpf|müde|arbeit|geld|arm|bildung|zugang|ungleich|schule/i,page:'6–9 und 10–11',reply:'Hier würde ich die Schuldfrage vom Lesetisch räumen. Eine fehlende Lesegelegenheit ist kein Beweis für fehlendes Können. Freiwalds Kritik am idealisierten Gestern fordert uns auf, nach den Menschen zu fragen, die in unserem Bild der Lesekultur fehlen. Welche Bedingungen machen Lesen überhaupt möglich?',question:'Welche konkrete Hürde meinst du – und welche Veränderung würde sie verringern? Was müsste neben einem guten Buch vorhanden sein?'},
evidence:{label:'Studien und Belege',pattern:/studie|pisa|daten|beleg|kompetenz|statistik|prozent|mess|nachweis/i,page:'5–6',reply:'Ein Befund kann eine wirkliche Krise anzeigen. Ich möchte ihn weder beschönigen noch grösser machen, als er ist. Freiwald stellt unterschiedliche Messgrössen nebeneinander: Häufigkeit, Vergnügen und Kompetenz. Wir müssen wissen, welche davon dein Beleg erfasst.',question:'Welche Gruppe, welcher Zeitraum und welche Aufgabe wurden untersucht? Welche deiner Schlussfolgerungen ist durch diesen Befund tatsächlich gedeckt?'},
nostalgia:{label:'Früher und heute',pattern:/früher|damals|vergangen|generation|nostalg|untergang|immer|alle/i,page:'2–3 und 6–9',reply:'Mein altes Pult ist kein Beweis für eine bessere Vergangenheit. Freiwald erinnert an frühere Warnungen vor falschem und übermässigem Lesen. Das widerlegt einen heutigen Schaden nicht; es macht aber den Massstab verdächtig, wenn wir eine ehemals allgemein lesende Gesellschaft voraussetzen.',question:'Wen schliesst dein Vergleich ein? Kannst du ein konkretes Früher benennen und erklären, warum die Bedingungen vergleichbar sind?'},
delegation:{label:'KI und Zusammenfassungen',pattern:/ki\b|chatgpt|zusammenfass|deleg|auslager|vertrau|algorithm/i,page:'9–11',reply:'Eine Zusammenfassung kann Zugang schaffen und zugleich eine Abhängigkeit erzeugen. Freiwald bringt delegiertes Lesen mit Vertrauen in Verbindung. Wenn jemand die Auswahl und Deutung übernimmt, muss ich fragen können, was weggelassen wurde. Auch meine Antworten sollten diese Prüfung aushalten.',question:'Welche Entscheidung würdest du einer Zusammenfassung überlassen, und welche Originalstelle müsstest du selbst lesen? Wie würdest du eine falsche Deutung bemerken?'},
pleasure:{label:'Lust, Wirkung und Leseerfahrung',pattern:/lust|spass|spaß|freud|roman|gefühl|berühr|empati|gern|langweil/i,page:'5–6',reply:'Dass ein Buch dich erreicht oder langweilt, ist eine wichtige Leseerfahrung. Es ist aber eine andere Aussage als ein Befund über Lesekompetenz. Freiwalds Hinweise zum Lesen aus Vergnügen stören das pauschale Ende des Lesens, ohne Schwierigkeiten beim Verstehen aufzulösen.',question:'An welcher konkreten Stelle entstand Nähe, Widerstand oder Langeweile? Was hat der Text dort getan – und was hast du als lesende Person beigetragen?'},
practice:{label:'Üben und etwas verändern',pattern:/üb|förder|helfen|unterstütz|versuch|verbesser|lösung|tun/i,page:'10–11',reply:'Dann lasse ich meinen Katalogstock liegen und frage nach einer Handlung. Freiwald richtet den Blick auf Lesefähigkeit und Förderung. Ein kleiner Versuch muss beobachtbar sein: nicht bloss mehr lesen wollen, sondern einen passenden Text verstehen, darüber sprechen und einen nächsten Schritt erkennen.',question:'Wie sähe dein Versuch morgen aus? Woran würdest du merken, dass er geholfen hat, und welche alternative Erklärung müsstest du berücksichtigen?'},
other:{label:'Meine Aussage genauer klären',pattern:/$a/,page:'5–11',reply:'Ich möchte dir keine Position unterschieben. Lass uns deine Aussage zuerst schärfen: Beschreibst du eine eigene Erfahrung, behauptest du eine allgemeine Entwicklung, oder schlägst du eine Handlung vor? Diese drei Arten von Aussagen brauchen unterschiedliche Antworten.',question:'Formuliere einen konkreten Satz und ein Beispiel. Was müsste ich akzeptieren, damit dein Argument trägt – und was könnte dagegen sprechen?'}
};
function foliantConversationReply(text,topic,kind){const t=foliantConversationTopics[topic]||foliantConversationTopics.other,history=state.data.readingConversation||[],previous=history.at(-1);let opening=kind==='observation'?'Deine Beobachtung nehme ich als Erfahrung ernst. Wie weit sie über diese Situation hinausreicht, müssen wir gesondert prüfen.':kind==='objection'?'Dein Einwand soll meine Position prüfen. Ich halte meine bisherige Deutung deshalb vorläufig und frage nach dem Punkt, an dem sie deinem Beispiel nicht standhält.':'Ich prüfe dein Argument auf seine Voraussetzung: Führt dein Beispiel wirklich zu der allgemeinen Schlussfolgerung, oder fehlt noch ein Zwischenschritt?';let memory=previous?(previous.topic===topic?'Wir bleiben bei derselben Frage. Vergleiche deine neue Aussage mit deiner vorherigen: „'+previous.text.slice(0,180)+'“. Was ergänzt oder korrigiert sie?':'Du wechselst die Perspektive. Vorhin ging es um „'+foliantConversationTopics[previous.topic].label+'“. Wie hängt deine neue Aussage damit zusammen?'):'';const same=previous?.topic===topic;const response=same?'Lass uns jetzt an deinem Beispiel weiterprüfen: Nenne die konkrete Textstelle oder Situation, den beobachteten Unterschied und eine mögliche andere Erklärung. Was würde deine Vermutung widerlegen? Wenn nichts sie widerlegen könnte, haben wir noch keine prüfbare Diagnose.':t.reply;return {text,topic,kind,reply:opening+' '+response+(memory?' '+memory:''),question:same?'Welche Antwort gibst du auf meine vorige Rückfrage? Benenne danach den stärksten Einwand gegen deine eigene Position.':t.question,page:t.page};}
function foliantConversationMarkup(){const history=state.data.readingConversation||[];return `<section class="foliant-conversation"><h4>Bleib am Lesetisch. Widersprich mir.</h4><p>Bring ein Argument, eine Beobachtung aus der Bibliothek oder einen Einwand ein. Wir können so lange weiterreden, wie du möchtest. Die vier Leitfragen oben geben dem Gespräch einen Textbezug.</p><div class="conversation-transcript" aria-live="polite">${history.map((t,i)=>`<article class="drama-action"><span class="eyebrow">Gesprächszug ${i+1} · ${esc(foliantConversationTopics[t.topic].label)}</span><p><b>Du:</b> ${esc(t.text)}</p><p><b>Herr Dr. Foliant:</b> ${esc(t.reply)}</p><div class="source-note">Freiwald · PDF S. ${esc(t.page)} · freie Paraphrase</div><p><b>Meine Rückfrage:</b> ${esc(t.question)}</p></article>`).join('')}</div><label for="conversation-kind">Was bringst du ein?</label><select id="conversation-kind"><option value="argument">Ein Argument</option><option value="observation">Eine eigene Beobachtung</option><option value="objection">Einen Einwand gegen Foliant</option></select><label for="conversation-input">${history.length?'Deine Antwort auf Foliants Rückfrage':'Dein Gesprächsbeitrag'}</label><textarea id="conversation-input" rows="4" placeholder="Beim Lesen ist mir aufgefallen … Ich widerspreche dir, weil … Mein Beispiel ist …">${esc(state.data.readingConversationDraft||'')}</textarea><label for="conversation-topic">Worauf soll Foliant eingehen?</label><select id="conversation-topic">${Object.entries(foliantConversationTopics).map(([id,t])=>`<option value="${id}" ${id==='other'?'selected':''}>${esc(t.label)}</option>`).join('')}</select><p id="conversation-detection" class="hint">Beim Schreiben schlage ich ein Thema vor. Du kannst es ändern.</p><button id="conversation-send" class="btn">Foliant meinen Beitrag vorlegen →</button><p id="conversation-status" role="status"></p><p class="hint">Dieses Gespräch läuft lokal mit erkennbaren Themen und vorbereiteten Antworten, ohne KI-Dienst. Foliant nimmt deinen Wortlaut und den vorigen Beitrag ins Gespräch auf; eine freie sprachliche Deutung kann er dabei nicht leisten. Neue Gesprächsantworten stehen zum Lesen bereit.</p></section>`;}
function foliantReadingDiscussionMarkup(){const turns=state.data.readingDiscussion||[],r=foliantReadingRounds[Math.min(turns.length,3)],done=turns.length>=4;return `<section class="foliant-drama"><span class="eyebrow">Textgespräch · Bent Freiwald</span><h3>Verlernen wir das Lesen?</h3><p>Herr Dr. Foliant eröffnet mit vier Leitfragen ein längeres Gespräch. Eigene Beiträge und Einwände kannst du unten jederzeit vorlegen. Er legt vier Fragen auf den Lesetisch. Du entscheidest, welchen Einwand du vertrittst; seine nächste Antwort greift diese Entscheidung auf. Alle Textbezüge sind Paraphrasen.</p><button data-debate-source="Freiwald">Originaltext aufschlagen →</button>${turns.map((t,i)=>`<article class="drama-action"><b>Runde ${i+1}: ${esc(foliantReadingRounds[i].question)}</b><p>Du: ${esc(foliantReadingRounds[i].options[t.choice])}</p><p>Dr. Foliant: ${esc(foliantReadingRounds[i].replies[t.choice])}</p><button data-foliant-say data-foliant-script="${esc(JSON.stringify([foliantReadingRounds[i].replies[t.choice]]))}">Antwort hören 🔊</button></article>`).join('')}${done?'<h4>Dein vorläufiges Urteil</h4><p>Formuliere jetzt deine Antwort auf die Ausgangsfrage: Welche Krise ist belegt, welcher Untergang ist bloss behauptet, und was möchtest du tun?</p>':`<h4>Runde ${turns.length+1} von 4</h4><p><b>Dr. Foliant:</b> ${esc(r.question)}</p><button data-foliant-say data-foliant-script="${esc(JSON.stringify([r.question,r.basis]))}">Foliant hören 🔊</button><div class="source-note"><b>Am Text prüfen · PDF S. ${r.page}</b><p>${esc(r.basis)}</p></div><div class="drama-choices">${r.options.map((o,i)=>`<button data-reading-choice="${i}">${esc(o)}</button>`).join('')}</div>`}${foliantConversationMarkup()}<label for="reading-discussion-note">Deine eigene Position und eine Textstelle</label><textarea id="reading-discussion-note" rows="5" placeholder="Ich unterscheide … Freiwald begründet auf Seite … Mein Einwand lautet …">${esc(state.data.readingDiscussionNote||'')}</textarea><button id="reading-discussion-save">Gespräch im Logbuch speichern</button><button id="reading-discussion-reset">Gespräch neu beginnen</button><p id="reading-discussion-status" role="status"></p><p>Die Gesprächswege sind redaktionell vorbereitet. Die Leitfragen reagieren auf deine Auswahl; das anschliessende Gespräch greift eigene Beiträge thematisch auf.</p></section>`;}
function foliantTrialState(){return state.data.foliantTrial||={act:0,mode:'rest',role:'Anklage',evidence:[],voices:[],notes:{}};}
const foliantTrialCards=[
{id:'competence',source:'Freiwald',title:'Eine Kompetenzkrise ist ernst',page:'5–6',text:'Kompetenzbefunde verlangen eine konkrete Diagnose. Sie belegen nicht automatisch den Verlust sämtlicher Leseweisen.',correct:true},
{id:'frequency',source:'Freiwald',title:'Buchhäufigkeit ist nicht Textverständnis',page:'5–6',text:'Vergnügen, Häufigkeit und Kompetenz sind unterschiedliche Messgrössen.',correct:true},
{id:'past',source:'Freiwald',title:'Das goldene Gestern ist ein fraglicher Massstab',page:'2–3 und 6–9',text:'Frühere Leseängste und ungleiche Teilhabe stören das Bild einer einst allgemein lesenden Gesellschaft.',correct:true},
{id:'delegate',source:'Freiwald',title:'Wer liest und urteilt für mich?',page:'9–11',text:'Delegiertes Lesen verlangt Vertrauen und die Möglichkeit, die Grundlage einer Deutung selbst zu prüfen.',correct:true},
{id:'all',source:'Freiwald',title:'Früher lasen alle tief und konzentriert',page:'2–3 und 6–9',text:'Diese absichtlich zugespitzte Behauptung ist durch unsere Textgrundlage nicht gedeckt.',correct:false}
];
function foliantTrialMarkup(){const d=foliantTrialState(),voices=sources.filter(s=>s[2].includes('Einzelbeitrag')),button=(act,label)=>`<button data-trial-act="${act}" class="btn">${label}</button>`,note=(key,label)=>`<label for="trial-note">${label}</label><textarea id="trial-note" data-trial-note="${key}" rows="4">${esc(d.notes[key]||'')}</textarea>`;const titles=['Borges: Alles vorhanden. Was fehlt?','Die Lesewette','Dein Urteil verändert den Raum','25 Gäste am Lesetisch','Der Prozess gegen die Gegenwart','Du korrigierst den Bibliothekar'];let body='';if(d.act===0)body=`<p><b>Herr Dr. Foliant:</b> Bevor wir über den Untergang urteilen, studieren wir Borges. Seine Bewohner haben alle Bücher und dennoch keinen sicheren Weg zum Sinn. Was fehlt ihnen?</p><button data-debate-source="Borges">Borges im Original lesen und studieren →</button>${note('borges','Halte ein Motiv und eine konkrete Stelle fest. Was bedeutet die Fülle für die Bewohner?')}<p>${state.data.borgesStudied?'Dein Borges-Studium ist festgehalten.':'Du kannst die Inszenierung frei erkunden. Für die geführte Reise beginnt dein Textstudium bei Borges.'}</p>${button(1,'Foliants Wette annehmen →')}`;
if(d.act===1)body=`<p><b>Herr Dr. Foliant:</b> Du meinst, wir verlernen das Lesen? Ich wette zunächst gegen deine Gewissheit. Lies denselben Absatz in zwei Situationen und beobachte, was sich verändert.</p><p class="hint">Dieser kurze Versuchstext ist für das Leselabor verfasst, kein Borges-Zitat und kein Kompetenztest.</p><div class="drama-choices"><button data-trial-mode="noise">Zuerst mit Unterbrechungen</button><button data-trial-mode="rest">Jetzt ungestört lesen</button></div><div class="trial-reading ${d.mode==='noise'?'trial-noise':''}"><p>Ein Katalog kann jedes Buch verzeichnen und dennoch verschweigen, warum wir es lesen sollten. Wer nur den Titel kennt, besitzt einen Hinweis, aber noch kein Urteil. Eine Zusammenfassung kann den Zugang erleichtern; zugleich bestimmt ihre Auswahl, was sichtbar wird. Deshalb hängt selbstständiges Lesen nicht daran, jede Hilfe abzulehnen. Es verlangt, eine entscheidende Behauptung am Text prüfen zu können.</p>${d.mode==='noise'?'<div class="trial-interrupt" aria-hidden="true">Neue Nachricht · Noch ein Fund · Schnell weiter?</div>':''}</div>${note('wager','Gib den Gedankengang in eigenen Worten wieder. Was änderte sich zwischen den beiden Leseweisen?')}<p><b>Foliant:</b> Der zweite Durchgang profitiert auch davon, dass du den Text schon kennst. Dein Erlebnis zeigt eine Möglichkeit; es beweist keinen gesellschaftlichen Trend.</p><button data-debate-source="Freiwald">Unterscheidungen bei Freiwald prüfen →</button>${button(2,'Eine Position im Raum erproben →')}`;
if(d.act===2)body=`<p><b>Herr Dr. Foliant:</b> Eine These soll nicht nur auf meinem Pult liegen. Trag sie durch die Bibliothek.</p><div class="drama-choices"><button data-trial-world="summary">Zusammenfassungen reichen mir</button><button data-trial-world="past">Früher war die Bibliothek für alle besser</button><button data-trial-world="open">Ich will die Originale selbst prüfen</button></div><p>Deine Wahl wirkt auf die Bücherwand. Stelle dieses Buch zurück und erlebe sie; öffne danach „Foliants Lesedrama“, um weiterzugehen.</p>${note('world','Was macht deine Entscheidung sichtbar – und was verdeckt sie?')}<button data-debate-source="Amlinger">Amlingers Perspektive hinzunehmen →</button>${button(3,'Die Gäste an den Tisch bitten →')}`;
if(d.act===3)body=`<p><b>Herr Dr. Foliant:</b> Wähle zwei Gäste. Lies ihre Originalbeiträge. Ihre Stimmen werden hier nicht erfunden: Die Karten geben unsere Orientierung und den jeweiligen Leseimpuls wieder.</p><div class="trial-voices">${voices.map(s=>`<article><button data-trial-voice="${s[0]}" aria-pressed="${d.voices.includes(s[0])}">${d.voices.includes(s[0])?'✓ ':''}${esc(s[1])}</button>${d.voices.includes(s[0])?`<p>${esc(s[3])}</p><p><i>${esc(s[4])}</i></p><button data-debate-source="${s[0]}">Originalbeitrag lesen →</button>`:''}</article>`).join('')}</div>${d.voices.length===2?`<p><b>Foliant:</b> Beide sitzen jetzt an deinem Tisch. Welche Erfahrung mit Lesen teilen sie, und wo geraten ihre Anliegen auseinander? Belege den Gegensatz mit je einer Stelle.</p>`:'Wähle zwei Stimmen für deine Gegenüberstellung.'}${note('voices','Ein gemeinsamer Gedanke, ein Gegensatz und zwei Textstellen. Welche Stimme verändert deine Position?')}${button(4,'Den Lesesaal als Gericht eröffnen →')}`;
if(d.act===4)body=`<p><b>Verhandelt wird:</b> „Wir verlernen das Lesen.“ Foliant schlägt mit seinem Katalogstock auf den Tisch. „Keine Anklage ohne Beleg. Keine Verteidigung ohne Gegenprobe.“</p><label for="trial-role">Deine Rolle</label><select id="trial-role">${['Anklage','Verteidigung','Zeuge'].map(r=>`<option ${d.role===r?'selected':''}>${r}</option>`).join('')}</select><p>${d.role==='Anklage'?'Zeige eine konkrete Fähigkeit, deren Verlust du behauptest.':d.role==='Verteidigung'?'Zeige, welche Formen des Lesens die pauschale Untergangsthese übersieht.':'Beschreibe eine eigene Erfahrung. Markiere, was du selbst beobachtet hast und was du daraus schliesst.'}</p>${foliantTrialCards.map(c=>`<article class="drama-action"><button data-trial-evidence="${c.id}" aria-pressed="${d.evidence.includes(c.id)}">${d.evidence.includes(c.id)?'✓ ':''}${esc(c.title)}</button><p>${esc(c.text)}</p><small>Freiwald · PDF S. ${c.page} · ${c.correct?'Paraphrase':'Foliants absichtliche Zuspitzung'}</small><button data-debate-source="${c.source}">Original prüfen →</button></article>`).join('')}${note('case','Begründe deine Position: Behauptung, Beleg, Reichweite und stärkster Gegenbeleg.')}<button data-trial-switch>Die Gegenseite übernehmen</button>${d.switched?'<p><b>Foliant:</b> Nun verteidige den stärksten Einwand gegen deine bisherige Position. Was musst du an deinem ersten Urteil einschränken?</p>':''}${button(5,'Foliant mit einem Gegenbeleg konfrontieren →')}`;
if(d.act===5)body=`<p><b>Foliants anfechtbare These:</b> ${d.correction==='past'?'<del>Früher lasen alle tief und konzentriert.</del>':'Früher lasen alle tief und konzentriert.'}</p><p>Lege einen Gegenbeleg auf mein Pult.</p><div class="drama-choices">${['past','competence','delegate'].map(id=>{const c=foliantTrialCards.find(c=>c.id===id);return `<button data-trial-correct="${id}">${c.title}</button>`;}).join('')}</div>${d.correction==='past'?'<p class="drama-reply"><b>Foliant korrigiert seinen Katalog:</b> Meine Behauptung war zu pauschal. Freiwalds historische Kritik trägt deinen Einwand. Ich ersetze „alle“ durch die Frage: Wer konnte unter welchen Bedingungen lesen? Diese Korrektur widerlegt heutige Kompetenzprobleme nicht.</p>':d.correction?'<p><b>Foliant:</b> Dein Beleg eröffnet eine wichtige andere Frage. Er widerlegt die historische Behauptung aber noch nicht unmittelbar. Welche Karte betrifft den Vergleich mit früher?</p>':''}${note('verdict','Dein vorläufiges Urteil: Was ist belegt, was offen? Welche konkrete Lesepraxis möchtest du erproben?')}<button data-trial-finish class="btn">Urteil festhalten und Bibliothek wieder öffnen</button><button data-trial-discussion>Im freien Textgespräch weiterdiskutieren →</button>`;
return `<section class="foliant-trial"><span class="eyebrow">Foliants Lesedrama · Akt ${d.act+1} von 6</span><h3>${titles[d.act]}</h3><nav class="trial-acts">${titles.map((t,i)=>`<button data-trial-act="${i}" aria-current="${d.act===i?'step':'false'}">${i+1} · ${t.split(':')[0]}</button>`).join('')}</nav>${body}<p class="hint">Die Rollen und Foliants Zuspitzungen sind inszeniert. Textbezüge sind gekennzeichnete Paraphrasen; dein Urteil wird nicht automatisch bewertet. Beobachtungen und Belege bleiben in diesem Browser.</p></section>`;}
function foliantTrialJournal(){const d=state.data.foliantTrial;if(!d)return '';return `<article class="journal-entry"><h3>Foliants Lesedrama · ${esc(d.role)}</h3>${Object.entries(d.notes).map(([key,text])=>`<h4>${esc({borges:'Borges',wager:'Lesewette',world:'Raumerfahrung',voices:'Zwei Essay-Stimmen',case:'Argument und Gegenargument',verdict:'Vorläufiges Urteil'}[key])}</h4><pre>${esc(text)}</pre>`).join('')}<p>Belege: ${d.evidence.map(id=>esc(foliantTrialCards.find(c=>c.id===id).title)).join(' · ')}</p><p>${d.correction==='past'?'Foliants historische These wurde korrigiert.':''}</p></article>`;}
